/* Contenido de «Alemán básico A1». Archivo generado con herramientas/dividir-catalogo.js: no se edita a mano. */
window.MARA_CONTENIDO("c-aleman-a1",{"l":{"c-aleman-a1-m1-l1":[{"tipo":"destacado","texto":"<b>Antes de empezar:</b> este es un <b>curso libre de capacitación</b> con constancia de Instituto Mara. Trabaja las habilidades del nivel <b>A1 del Marco Común Europeo (MCER)</b>: el de quien empieza y ya puede presentarse, dar sus datos y resolver situaciones sencillas de la vida diaria. <b>No es una certificación oficial de alemán</b> como el <b>Goethe-Zertifikat A1</b>, ni tiene validez oficial ante la SEP. Si una empresa, una universidad o un trámite de visa te pide un nivel certificado, tendrás que presentar ese examen por tu cuenta en un centro autorizado, como el Goethe-Institut."},{"tipo":"texto","texto":"Tranquilo: el alemán tiene fama de difícil, pero tiene muchas cosas a tu favor. Se lee casi como se escribe, muchas palabras se parecen al inglés (<i>Hotel, Taxi, Hand, Haus</i>) y con cinco o seis saludos ya quedas bien en cualquier lugar. Vamos paso a paso.<br><br><b>Cómo leer la pronunciación aproximada</b> que verás en todo el curso: la sílaba con acento lleva tilde (<b>gúten</b>); <b>ü</b> = di «i» con los labios en forma de «u»; <b>ö</b> = di «e» con los labios redondos; <b>j</b> = nuestra j de «jamón»; <b>ij</b> = una j muy suave, casi un siseo, como en <i>ich</i>; <b>sh</b> = como cuando pides silencio; <b>ts</b> = como en «pizza»; <b>h</b> = una h que sí suena, como un suspiro suave; <b>z</b> = una s que zumba, como abeja. La r alemana se hace en la garganta, y al final de palabra casi se vuelve una «a»: <i>Lehrer</i> suena «léra»."},{"tipo":"tabla","titulo":"Saludos y despedidas","voz":true,"colVoz":0,"encabezados":["Alemán","Se lee aprox.","Español","Cuándo"],"filas":[["Hallo!","hálo","¡Hola!","Con casi todos; es informal pero muy común"],["Guten Morgen!","gúten mórguen","Buenos días","En la mañana, más o menos hasta las 11"],["Guten Tag!","gúten taak","Buenos días / Buenas tardes","Durante el día; más formal"],["Guten Abend!","gúten ábent","Buenas noches (al llegar)","En la noche, al saludar"],["Gute Nacht!","gúte naajt","Buenas noches (al irse a dormir)","Solo para despedirte antes de dormir"],["Tschüss!","chüs","¡Bye! / Adiós","Informal: amigos, compañeros, tiendas"],["Auf Wiedersehen!","auf víder-zéen","Adiós / Hasta luego","Formal; siempre funciona"],["Bis morgen!","bis mórguen","¡Hasta mañana!","Si se ven al día siguiente"],["Schönen Tag noch!","shönen taak noj","¡Que tengas buen día!","Al despedirte de día"],["Danke! / Danke schön!","dánke / dánke shön","¡Gracias! / ¡Muchas gracias!","Siempre"],["Bitte.","bíte","Por favor · De nada","Sirve para las dos cosas"]],"nota":"En el sur de Alemania (Múnich) y en Austria oirás <b>Grüß Gott!</b> (buenos días) y <b>Servus!</b> (hola / adiós entre conocidos). En el norte, <b>Moin!</b> a cualquier hora. Con <i>Hallo</i> y <i>Guten Tag</i> te entienden en todas partes."},{"tipo":"comparar","titulo":"«Buenas noches» no siempre es Gute Nacht","malTitulo":"Evita","mal":"Llegar a un restaurante a las 9 p. m. y decir <i>Gute Nacht!</i><br>Contestar <i>Danke</i> cuando alguien te da las gracias.","bienTitulo":"Correcto","bien":"<i><b>Guten Abend!</b></i> para saludar en la noche. <i>Gute Nacht</i> es solo para irse a dormir.<br>Si te dicen <i>Danke!</i>, contestas <i><b>Bitte!</b></i> o <i><b>Gern geschehen!</b></i> (de nada)."},{"tipo":"dialogo","titulo":"Diálogo — Recepción de un hotel en Cancún","lineas":[{"quien":"Karla","en":"Guten Tag! Willkommen in Cancún!","es":"¡Buenas tardes! ¡Bienvenida a Cancún!"},{"quien":"Frau Weber","en":"Guten Tag! Vielen Dank.","es":"¡Buenas tardes! Muchas gracias."},{"quien":"Karla","en":"Wie geht es Ihnen?","es":"¿Cómo está?"},{"quien":"Frau Weber","en":"Gut, danke. Und Ihnen?","es":"Bien, gracias. ¿Y usted?"},{"quien":"Karla","en":"Sehr gut, danke. Hier ist Ihr Schlüssel.","es":"Muy bien, gracias. Aquí está su llave."},{"quien":"Frau Weber","en":"Danke schön!","es":"¡Muchas gracias!"},{"quien":"Karla","en":"Bitte schön! Schönen Tag noch!","es":"¡De nada! ¡Que tenga buen día!"},{"quien":"Frau Weber","en":"Danke, gleichfalls!","es":"¡Gracias, igualmente!"}]},{"tipo":"practica","rotulo":"¿Qué dices?","preguntas":[{"p":"Son las 9 de la noche y llegas a la recepción del hotel. Dices…","ops":["Gute Nacht!","Guten Abend!","Guten Morgen!"],"correcta":1,"explica":"Para <b>saludar</b> en la noche: <b>Guten Abend</b>. <i>Gute Nacht</i> es para irse a dormir."},{"p":"Son las 8 de la mañana y entras a la oficina.","ops":["Guten Morgen!","Guten Abend!","Gute Nacht!"],"correcta":0},{"p":"Te despides de un compañero de trabajo con el que te llevas bien.","ops":["Guten Tag!","Tschüss! Bis morgen!","Willkommen!"],"correcta":1},{"p":"Alguien te dice <i>Danke schön!</i> Tú contestas…","ops":["Danke!","Bitte schön!","Tschüss!"],"correcta":1,"explica":"<b>Bitte</b> significa «por favor», pero también «de nada»."},{"p":"Te dicen <i>Schönen Tag noch!</i> Una respuesta natural es…","ops":["Guten Morgen!","Gute Nacht!","Danke, gleichfalls!"],"correcta":2,"explica":"<b>gleichfalls</b> = igualmente."}]},{"tipo":"relacionar","rotulo":"Relaciona cada fórmula con su significado","voz":true,"pares":[["Auf Wiedersehen","Adiós (formal)"],["Bis morgen","Hasta mañana"],["Gern geschehen","De nada"],["Willkommen","Bienvenido"],["Vielen Dank","Muchas gracias"],["Gleichfalls","Igualmente"]]},{"tipo":"pronunciar","rotulo":"Dilo en voz alta","frases":[{"en":"Guten Morgen!","pron":"gúten mórguen","es":"¡Buenos días!"},{"en":"Guten Abend!","pron":"gúten ábent","es":"¡Buenas noches! (al llegar)"},{"en":"Danke schön!","pron":"dánke shön","es":"¡Muchas gracias!"},{"en":"Tschüss, bis morgen!","pron":"chüs, bis mórguen","es":"¡Bye, hasta mañana!"},{"en":"Auf Wiedersehen!","pron":"auf víder-zéen","es":"¡Adiós!"}]},{"tipo":"clave","items":["<b>Guten Morgen</b> en la mañana, <b>Guten Tag</b> de día y <b>Guten Abend</b> en la noche; <i>Gute Nacht</i> solo para dormir.","<b>Tschüss</b> es informal; <b>Auf Wiedersehen</b> funciona siempre.","<b>Bitte</b> = por favor y también «de nada».","Este curso es libre, con constancia de Instituto Mara; no sustituye el Goethe-Zertifikat A1."]}],"c-aleman-a1-m1-l2":[{"tipo":"texto","texto":"Como en español, el alemán tiene <b>du</b> (tú) y <b>Sie</b> (usted). Tres detalles que conviene saber desde hoy:<br><b>1)</b> <b>Sie</b> de usted siempre se escribe con <b>S mayúscula</b>, y sirve también para «ustedes» en plan formal.<br><b>2)</b> Para «ustedes» con amigos o familia se usa <b>ihr</b>. En México decimos «ustedes» a todos; en alemán tienes que elegir: <i>ihr</i> (de confianza) o <i>Sie</i> (formal).<br><b>3)</b> En Alemania el <i>Sie</i> se usa con desconocidos, clientes, jefes y personas mayores. Entre compañeros jóvenes el <i>du</i> llega rápido, pero lo propone la persona mayor o de más rango: <i>Wollen wir uns duzen?</i> (¿Nos hablamos de tú?). Si dudas, usa <i>Sie</i>: nadie se ofende."},{"tipo":"tabla","titulo":"Las mismas preguntas, dos registros","voz":true,"colVoz":0,"encabezados":["Alemán","Registro","Español"],"filas":[["Wie geht's?","du","¿Qué tal? / ¿Cómo estás?"],["Wie geht es dir?","du","¿Cómo estás?"],["Wie geht es Ihnen?","Sie","¿Cómo está usted?"],["Gut, danke. Und dir?","du","Bien, gracias. ¿Y tú?"],["Gut, danke. Und Ihnen?","Sie","Bien, gracias. ¿Y usted?"],["Mir geht es gut.","los dos","Estoy bien."],["Es geht.","los dos","Más o menos."],["Nicht so gut.","los dos","No muy bien."],["Entschuldigung!","los dos","¡Perdón! / ¡Disculpe!"]],"nota":"<i>Wie geht's?</i> es la forma corta de <i>Wie geht es?</i> Literalmente es «¿cómo va?», por eso la respuesta es <i>Mir geht es gut</i>: «a mí me va bien»."},{"tipo":"comparar","titulo":"«¿Cómo estás?» no se traduce palabra por palabra","malTitulo":"Evita","mal":"<i>Wie bist du?</i> (suena a «¿cómo eres?»)<br><i>Ich bin gut.</i> (suena a «soy bueno», como presumiendo)<br><i>sie</i> con minúscula para decir «usted»","bienTitulo":"Correcto","bien":"<i><b>Wie geht's?</b> / <b>Wie geht es Ihnen?</b></i><br><i><b>Mir geht es gut</b>, danke.</i> o simplemente <i>Gut, danke.</i><br><i><b>Sie</b></i> con mayúscula = usted · <i>sie</i> con minúscula = ella o ellos"},{"tipo":"dialogo","titulo":"Diálogo — Oficina de una planta automotriz en Puebla","lineas":[{"quien":"Jonas","en":"Hallo, Diego! Wie geht's?","es":"¡Hola, Diego! ¿Qué tal?"},{"quien":"Diego","en":"Hallo, Jonas! Gut, danke. Und dir?","es":"¡Hola, Jonas! Bien, gracias. ¿Y tú?"},{"quien":"Jonas","en":"Auch gut. Diego, das ist Frau Schmidt, unsere Chefin.","es":"También bien. Diego, ella es la señora Schmidt, nuestra jefa."},{"quien":"Diego","en":"Guten Tag, Frau Schmidt. Freut mich. Wie geht es Ihnen?","es":"Buenos días, señora Schmidt. Mucho gusto. ¿Cómo está?"},{"quien":"Frau Schmidt","en":"Sehr gut, danke. Und Ihnen?","es":"Muy bien, gracias. ¿Y usted?"},{"quien":"Diego","en":"Mir geht es gut, danke.","es":"Estoy bien, gracias."}]},{"tipo":"practica","rotulo":"¿Du, ihr o Sie?","preguntas":[{"p":"Hablas con un niño de 8 años.","ops":["du","Sie","ihr"],"correcta":0},{"p":"Atiendes a un huésped en el hotel.","ops":["du","ihr","Sie"],"correcta":2,"explica":"Con clientes, siempre <b>Sie</b>."},{"p":"Les hablas a dos amigos a la vez («¿ustedes vienen?»).","ops":["Sie","ihr","du"],"correcta":1,"explica":"«Ustedes» de confianza = <b>ihr</b>."},{"p":"Le preguntas una dirección a un desconocido en la calle.","ops":["Sie","du","ihr"],"correcta":0,"explica":"Con desconocidos adultos, <b>Sie</b>."},{"p":"«Estoy bien, gracias» se dice…","ops":["Ich bin gut, danke.","Mir geht es gut, danke.","Mich geht es gut, danke."],"correcta":1}]},{"tipo":"completar","rotulo":"Completa el saludo","voz":true,"items":[{"frase":"Wie geht es ___?","resp":["Ihnen"],"es":"¿Cómo está usted?"},{"frase":"Gut, danke. Und ___?","resp":["dir"],"es":"Bien, gracias. ¿Y tú?"},{"frase":"Mir geht es ___, danke.","resp":["gut"],"es":"Estoy bien, gracias."},{"frase":"Hallo, Jonas! Wie ___'s?","resp":["geht"],"es":"¡Hola, Jonas! ¿Qué tal?"},{"frase":"Entschuldigung, sind ___ Herr Müller?","resp":["Sie"],"es":"Disculpe, ¿es usted el señor Müller?"}]},{"tipo":"escuchar","rotulo":"Escucha y repite","frases":[{"en":"Wie geht es Ihnen?","pron":"vi guet es ínen","es":"¿Cómo está usted?"},{"en":"Gut, danke. Und dir?","pron":"gut, dánke. unt dia","es":"Bien, gracias. ¿Y tú?"},{"en":"Mir geht es sehr gut.","pron":"mia guet es zea gut","es":"Estoy muy bien."},{"en":"Wollen wir uns duzen?","pron":"vólen via uns dútsen","es":"¿Nos hablamos de tú?"}]},{"tipo":"clave","items":["<b>du</b> con amigos, familia y niños; <b>Sie</b> con clientes, jefes y desconocidos.","«Ustedes» de confianza = <b>ihr</b>; formal = <b>Sie</b>.","<b>Sie</b> (usted) siempre con mayúscula.","«Estoy bien» = <i><b>Mir geht es gut</b></i>, no <i>ich bin gut</i>."]}],"c-aleman-a1-m1-l3":[{"tipo":"texto","texto":"Con cuatro frases ya te puedes presentar: <b>Ich heiße…</b> (me llamo), <b>Ich komme aus…</b> (soy de, literalmente «vengo de»), <b>Ich wohne in…</b> (vivo en) y <b>Ich arbeite bei…</b> (trabajo en, con el nombre de la empresa). Dos detalles: nuestro país se escribe <b>Mexiko</b>, con k, y la capital es <b>Mexiko-Stadt</b>. Y al decir tu nacionalidad o tu profesión <b>no se usa artículo</b>: <i>Ich bin Mexikaner</i>, igual que en español «soy mexicano». La letra <b>ß</b> de <i>heiße</i> se lee como una s normal."},{"tipo":"tabla","titulo":"Frases para presentarte","voz":true,"colVoz":0,"encabezados":["Alemán","Español"],"filas":[["Ich heiße Laura.","Me llamo Laura."],["Mein Name ist Diego Ramírez.","Mi nombre es Diego Ramírez. (más formal)"],["Ich komme aus Mexiko.","Soy de México."],["Ich bin Mexikaner.","Soy mexicano."],["Ich bin Mexikanerin.","Soy mexicana."],["Ich wohne in Querétaro.","Vivo en Querétaro."],["Ich arbeite bei Volkswagen.","Trabajo en Volkswagen."],["Wie heißen Sie?","¿Cómo se llama usted?"],["Wie heißt du?","¿Cómo te llamas?"],["Woher kommen Sie?","¿De dónde es usted?"],["Freut mich!","¡Mucho gusto!"]],"nota":"A <i>Freut mich!</i> se contesta <i>Freut mich auch!</i> (el gusto es mío). Fíjate: la mujer agrega <b>-in</b>: <i>Mexikaner → Mexikaner<b>in</b></i>. Lo verás a fondo en el módulo 2."},{"tipo":"comparar","titulo":"Calcos que delatan al hispanohablante","malTitulo":"Evita","mal":"<i>Ich bin ein Mexikaner.</i><br><i>Ich bin von Mexiko.</i><br><i>Ich wohne en Monterrey.</i>","bienTitulo":"Correcto","bien":"<i>Ich bin Mexikaner.</i> (sin <i>ein</i>)<br><i>Ich <b>komme aus</b> Mexiko.</i><br><i>Ich wohne <b>in</b> Monterrey.</i>"},{"tipo":"dialogo","titulo":"Diálogo — Recorrido turístico en Oaxaca","lineas":[{"quien":"Rodrigo","en":"Guten Morgen! Ich heiße Rodrigo. Ich bin heute Ihr Reiseleiter.","es":"¡Buenos días! Me llamo Rodrigo. Hoy soy su guía."},{"quien":"Anna","en":"Guten Morgen, Rodrigo! Ich bin Anna, und das ist mein Mann, Thomas.","es":"¡Buenos días, Rodrigo! Yo soy Anna, y él es mi esposo, Thomas."},{"quien":"Thomas","en":"Freut mich!","es":"¡Mucho gusto!"},{"quien":"Rodrigo","en":"Freut mich auch! Woher kommen Sie?","es":"¡Igualmente! ¿De dónde son?"},{"quien":"Anna","en":"Wir kommen aus Deutschland, aus Hamburg. Und Sie? Kommen Sie aus Oaxaca?","es":"Somos de Alemania, de Hamburgo. ¿Y usted? ¿Es de Oaxaca?"},{"quien":"Rodrigo","en":"Ja, ich komme aus Oaxaca, aber ich wohne in Mexiko-Stadt.","es":"Sí, soy de Oaxaca, pero vivo en la Ciudad de México."}]},{"tipo":"practica","rotulo":"Elige la opción correcta","preguntas":[{"p":"«Me llamo Sofía»","ops":["Ich heiße Sofía.","Ich bin heiße Sofía.","Mich heiße Sofía."],"correcta":0},{"p":"«Soy de México»","ops":["Ich bin von Mexiko.","Ich komme aus Mexiko.","Ich komme in Mexiko."],"correcta":1,"explica":"El origen se dice con <b>kommen aus</b>."},{"p":"Una mujer dice «Soy mexicana».","ops":["Ich bin Mexikaner.","Ich bin eine Mexiko.","Ich bin Mexikanerin."],"correcta":2,"explica":"Femenino con <b>-in</b> y sin artículo."},{"p":"«¿De dónde es usted?»","ops":["Woher kommen Sie?","Wo wohnst du?","Wie heißen Sie?"],"correcta":0},{"p":"Te dicen <i>Freut mich!</i> Contestas…","ops":["Bitte!","Freut mich auch!","Gute Nacht!"],"correcta":1}]},{"tipo":"ordenar","rotulo":"Arma la presentación","voz":true,"items":[{"frase":"Ich heiße Ana und ich komme aus Mexiko.","es":"Me llamo Ana y soy de México.","otras":["Ich komme aus Mexiko und ich heiße Ana."]},{"frase":"Ich wohne in Monterrey.","es":"Vivo en Monterrey.","otras":["In Monterrey wohne ich."]},{"frase":"Ich arbeite in einem Hotel.","es":"Trabajo en un hotel.","otras":["In einem Hotel arbeite ich."]},{"frase":"Woher kommen Sie?","es":"¿De dónde es usted?"}]},{"tipo":"pronunciar","rotulo":"Preséntate en voz alta","frases":[{"en":"Ich heiße Diego.","pron":"ij háise diégo","es":"Me llamo Diego."},{"en":"Ich komme aus Mexiko.","pron":"ij kóme aus méksiko","es":"Soy de México."},{"en":"Ich bin Mexikanerin.","pron":"ij bin meksikánerin","es":"Soy mexicana."},{"en":"Ich wohne in Puebla.","pron":"ij vóne in puebla","es":"Vivo en Puebla."},{"en":"Freut mich!","pron":"froit mij","es":"¡Mucho gusto!"}]},{"tipo":"reflexion","rotulo":"Tu presentación","pregunta":"Escribe tu presentación en cuatro frases: tu nombre, de dónde eres, la ciudad donde vives y dónde trabajas o estudias. Luego dila en voz alta tres veces, sin leer.","ayuda":"Hallo! Ich heiße… Ich komme aus Mexiko, aus… Ich wohne in… Ich arbeite bei… / Ich bin Student / Studentin."},{"tipo":"clave","items":["<i>Ich heiße…, ich komme aus…, ich wohne in…, ich arbeite bei…</i>","Nacionalidad y profesión sin artículo: <i>Ich bin Mexikaner</i>.","La mujer agrega <b>-in</b>: <i>Mexikanerin</i>.","<b>Mexiko</b> con k; la capital es <b>Mexiko-Stadt</b>."]}],"c-aleman-a1-m1-l4":[{"tipo":"texto","texto":"<b>Sein</b> es el verbo más importante del alemán y cubre lo que en español dividimos entre <b>ser</b> y <b>estar</b>: <i>Ich bin Mexikaner</i> (soy), <i>Ich bin müde</i> (estoy cansado), <i>Ich bin in Berlin</i> (estoy en Berlín). Una buena noticia: una sola palabra para dos verbos. Una diferencia con el español: en alemán <b>el pronombre es obligatorio</b>. Decimos «soy de León»; en alemán nunca se quita el <i>ich</i>."},{"tipo":"tabla","titulo":"Sein en presente","voz":true,"colVoz":0,"encabezados":["Alemán","Se lee aprox.","Español"],"filas":[["ich bin","ij bin","yo soy / estoy"],["du bist","du bist","tú eres / estás"],["er ist","er ist","él es / está"],["sie ist","zi ist","ella es / está"],["es ist","es ist","es / está (cosas)"],["wir sind","via zint","nosotros somos / estamos"],["ihr seid","ía zait","ustedes son (de confianza)"],["sie sind","zi zint","ellos / ellas son"],["Sie sind","zi zint","usted es · ustedes son (formal)"]],"nota":"La palabra <b>sie</b> tiene tres caras: <i>sie ist</i> = ella es; <i>sie sind</i> = ellos son; <i>Sie sind</i> (mayúscula) = usted es. El verbo y la mayúscula te dicen cuál es."},{"tipo":"comparar","titulo":"No quites el pronombre","malTitulo":"Evita","mal":"<i>Bin müde.</i><br><i>Er sind Lehrer.</i><br><i>Ist aus Mexiko.</i>","bienTitulo":"Correcto","bien":"<i><b>Ich</b> bin müde.</i><br><i>Er <b>ist</b> Lehrer.</i><br><i><b>Sie</b> ist aus Mexiko.</i> (ella es de México)"},{"tipo":"escuchar","rotulo":"Escucha frases con sein","frases":[{"en":"Das ist mein Kollege Jonas.","pron":"das ist main kolégue yónas","es":"Él es mi compañero de trabajo, Jonas."},{"en":"Sie ist sehr nett.","pron":"zi ist zea net","es":"Ella es muy amable."},{"en":"Wir sind aus Guadalajara.","es":"Somos de Guadalajara."},{"en":"Sind Sie Deutsche?","pron":"zint zi dóiche","es":"¿Usted es alemana?"},{"en":"Ihr seid super!","pron":"ía zait zúpa","es":"¡Ustedes son geniales!"},{"en":"Ich bin müde.","pron":"ij bin mǘde","es":"Estoy cansado."}]},{"tipo":"practica","rotulo":"Elige la forma de sein","preguntas":[{"p":"Wir ___ aus Mexiko.","ops":["seid","sind","ist"],"correcta":1},{"p":"___ Sie der neue Techniker?","ops":["Sind","Bist","Ist"],"correcta":0,"explica":"Con <b>Sie</b> (usted), el verbo va en la forma de «ellos»: <b>sind</b>."},{"p":"Maria und Sofía ___ Kolleginnen.","ops":["ist","seid","sind"],"correcta":2,"explica":"Dos personas = <b>sie sind</b>."},{"p":"Jonas und Lukas, ___ ihr müde?","ops":["seid","sind","bist"],"correcta":0},{"p":"«Estoy cansada» (lo dice una mujer)","ops":["Bin müde.","Ich bin müde.","Ich ist müde."],"correcta":1,"explica":"En alemán el adjetivo no cambia aquí: <i>müde</i> sirve para hombre y mujer."}]},{"tipo":"completar","rotulo":"Completa con sein","voz":true,"items":[{"frase":"Wir ___ aus Monterrey.","resp":["sind"],"es":"Somos de Monterrey."},{"frase":"___ Sie Lehrer?","resp":["Sind"],"es":"¿Usted es maestro?"},{"frase":"Sie ___ aus Berlin.","resp":["ist"],"es":"Ella es de Berlín."},{"frase":"Du ___ müde?","resp":["bist"],"es":"¿Estás cansado?"},{"frase":"Ihr ___ sehr nett.","resp":["seid"],"es":"Ustedes son muy amables."},{"frase":"Ich ___ in Berlin.","resp":["bin"],"es":"Estoy en Berlín."}]},{"tipo":"tarjetas","rotulo":"Memoriza sein","voz":true,"vozEn":"reverso","instruccion":"Ves la forma en español; di la forma en alemán antes de voltear.","tarjetas":[{"frente":"yo soy / estoy","reverso":"ich bin","ej":"Ich bin aus Puebla."},{"frente":"tú eres / estás","reverso":"du bist","ej":"Du bist nett."},{"frente":"ella es / está","reverso":"sie ist","ej":"Sie ist Ingenieurin."},{"frente":"nosotros somos","reverso":"wir sind","ej":"Wir sind Kollegen."},{"frente":"ustedes son (de confianza)","reverso":"ihr seid","ej":"Ihr seid super!"},{"frente":"usted es","reverso":"Sie sind","ej":"Sind Sie Frau Weber?"}]},{"tipo":"clave","items":["<b>sein</b> = ser y estar: <i>ich bin, du bist, er/sie/es ist, wir sind, ihr seid, sie/Sie sind</i>.","El pronombre (<i>ich, du, er…</i>) nunca se quita.","<i>sie ist</i> = ella · <i>sie sind</i> = ellos · <i>Sie sind</i> = usted.","Con <b>Sie</b> (usted) el verbo va igual que con «ellos»."]}],"c-aleman-a1-m1-l5":[{"tipo":"texto","texto":"La mejor noticia del alemán: <b>se lee casi siempre como se escribe</b>. Solo necesitas aprender unas cuantas combinaciones que en español suenan distinto, y listo. Tres pistas más: la <b>h</b> después de vocal no suena, solo alarga la vocal (<i>Bahn</i> = «baan»); la <b>j</b> suena como «y» (<i>ja</i> = «ya»); y la <b>ß</b> es una s normal (<i>Straße</i> = «shtráse»).<br><br><b>Las mayúsculas:</b> en alemán <b>todos los sustantivos</b> se escriben con mayúscula, estén donde estén: <i>Ich trinke <b>K</b>affee im <b>H</b>otel.</i> No es un error: te ayuda a encontrar las cosas y las personas en la frase."},{"tipo":"tabla","titulo":"Los sonidos clave","voz":true,"colVoz":1,"encabezados":["Letras","Ejemplos","Cómo se dicen"],"filas":[["ä","Käse, spät, Mädchen","Como nuestra «e»: <i>Käse</i> = «kése» (queso)."],["ö","schön, hören, Köln","Di «e» y redondea los labios como para besar."],["ü","fünf, München, Tschüss","Di «i» con los labios en forma de «u», como para silbar."],["ch (tras a, o, u)","acht, Buch, Nacht","Como nuestra j: «ajt», «buj», «naajt»."],["ch (tras e, i, ä, ö, ü, ei, eu o consonante)","ich, nicht, Milch","Una j muy suave, casi un siseo, con la boca sonriendo."],["sch","Schule, schön, Tisch","Como «sh», como cuando pides silencio."],["ei","nein, drei, Wein","Suena «ai»: «nain», «drai», «vain»."],["ie","vier, Bier, Wien","Suena «i» larga: «fía», «bía», «viin»."],["eu / äu","neu, Euro, Häuser","Suena «oi»: «noi», «óiro»."],["w","Wasser, wie, Wein","Como una «v» hecha con los dientes sobre el labio."],["v","vier, Vater, viel","Casi siempre como «f»: «fía», «fáter»."],["z","zehn, Zimmer, Pizza","Como «ts»: «tsen», «tsímer»."],["s + vocal al inicio","sieben, Salat, Sonne","Una s que zumba, como abeja: «zíben»."],["st / sp al inicio","Straße, Stadt, sprechen","Se dicen «sht» y «shp»: «shtat», «shpréjen»."]]},{"tipo":"comparar","titulo":"ei o ie: una letra cambia todo","malTitulo":"Evita","mal":"Leer letra por letra, como en español: <i>Wein</i> «ve-in», <i>Wien</i> «vi-en», <i>vier</i> «vi-er».","bienTitulo":"Correcto","bien":"<b>ei</b> = «ai» · <b>ie</b> = «i» larga.<br><i>Wein</i> = «vain» (vino) · <i>Wien</i> = «viin» (Viena) · <i>vier</i> = «fía» (cuatro).<br>Truco: se pronuncia <b>la segunda letra</b> como en inglés: e<b>i</b> → «ai», i<b>e</b> → «i»."},{"tipo":"escuchar","rotulo":"Escucha las parejas","frases":[{"en":"Wein und Wien","pron":"vain unt viin","es":"vino y Viena"},{"en":"schon und schön","pron":"shon unt shön","es":"ya y bonito"},{"en":"Mutter und Mütter","pron":"múta unt mǘta","es":"madre y madres"},{"en":"acht und ich","pron":"ajt unt ij","es":"ocho y yo"},{"en":"Zimmer und sieben","pron":"tsíma unt zíben","es":"habitación y siete"},{"en":"Straße und Schule","pron":"shtráse unt shúle","es":"calle y escuela"}]},{"tipo":"practica","rotulo":"¿Cómo suena?","preguntas":[{"p":"¿Cómo se lee <i>drei</i> (tres)?","ops":["«drai»","«drei», como en español","«dri»"],"correcta":0,"explica":"<b>ei</b> siempre suena «ai»."},{"p":"¿Cómo se lee <i>Bier</i> (cerveza)?","ops":["«bai-er»","«bía», con i larga","«bi-er»"],"correcta":1},{"p":"La <b>z</b> de <i>zehn</i> (diez) suena…","ops":["como la s de «sal»","como la z de España","como «ts»"],"correcta":2},{"p":"La <b>v</b> de <i>Vater</i> (padre) suena casi siempre como…","ops":["f","b","u"],"correcta":0},{"p":"En <i>Ich trinke Kaffee im Hotel</i>, ¿por qué <i>Kaffee</i> y <i>Hotel</i> van con mayúscula?","ops":["Porque son marcas","Porque todos los sustantivos van con mayúscula","Porque son palabras extranjeras"],"correcta":1}]},{"tipo":"pronunciar","rotulo":"Entrena la boca","frases":[{"en":"Das Zimmer ist schön.","pron":"das tsíma ist shön","es":"La habitación está bonita."},{"en":"Ich trinke Wasser, nicht Wein.","pron":"ij trínke vása, nijt vain","es":"Tomo agua, no vino."},{"en":"Vier Bier, bitte!","pron":"fía bía, bíte","es":"¡Cuatro cervezas, por favor!"},{"en":"Ich spreche ein bisschen Deutsch.","pron":"ij shpréje ain bísjen doich","es":"Hablo un poco de alemán."},{"en":"Tschüss, bis Montag!","pron":"chüs, bis móntaak","es":"¡Bye, hasta el lunes!"}]},{"tipo":"clave","items":["<b>ä</b> = e · <b>ö</b> = e con labios redondos · <b>ü</b> = i con labios redondos.","<b>ei</b> = «ai» · <b>ie</b> = «i» · <b>eu</b> = «oi» · <b>sch</b> = «sh».","<b>w</b> = v · <b>v</b> = f · <b>z</b> = ts · <b>st/sp</b> al inicio = sht / shp.","Todos los sustantivos van con mayúscula. Pasa a la evaluación: necesitas 80%."]}],"c-aleman-a1-m2-l1":[{"tipo":"texto","texto":"Del 0 al 12 los números son palabras nuevas, pero cortas. Del 13 al 19 se forman con <b>-zehn</b> (diez): <i>dreizehn</i> = «tres-diez». Las decenas terminan en <b>-zig</b>, salvo el 30: <i>dreißig</i>. Y aquí viene la sorpresa: <b>del 21 al 99 el alemán dice primero la unidad y luego la decena</b>: 45 es <i>fünfundvierzig</i>, literalmente «cinco y cuarenta». Suena raro los primeros días, pero se vuelve automático. Un truco al anotar un número que te dictan: escribe primero el segundo dígito."},{"tipo":"tabla","titulo":"Del 0 al 20","voz":true,"colVoz":1,"encabezados":["Número","Alemán","Se lee aprox."],"filas":[["0","null","nul"],["1","eins","ains"],["2","zwei","tsvai"],["3","drei","drai"],["4","vier","fía"],["5","fünf","fünf"],["6","sechs","zeks"],["7","sieben","zíben"],["8","acht","ajt"],["9","neun","noin"],["10","zehn","tsen"],["11","elf","elf"],["12","zwölf","tsvölf"],["13","dreizehn","dráitsen"],["14","vierzehn","fírtsen"],["15","fünfzehn","fǘnftsen"],["16","sechzehn","zéjtsen"],["17","siebzehn","zíptsen"],["18","achtzehn","ájtsen"],["19","neunzehn","nóintsen"],["20","zwanzig","tsvántsij"]],"nota":"Fíjate en 16 y 17: pierden letras (<i>sech<b>s</b></i> → <i>sechzehn</i>; <i>sieb<b>en</b></i> → <i>siebzehn</i>)."},{"tipo":"tabla","titulo":"Las decenas y los números «al revés»","voz":true,"colVoz":1,"encabezados":["Número","Alemán","Literalmente"],"filas":[["21","einundzwanzig","uno y veinte"],["22","zweiundzwanzig","dos y veinte"],["30","dreißig","treinta (¡con ß, no con z!)"],["35","fünfunddreißig","cinco y treinta"],["40","vierzig","cuarenta"],["50","fünfzig","cincuenta"],["60","sechzig","sesenta"],["70","siebzig","setenta"],["80","achtzig","ochenta"],["90","neunzig","noventa"],["99","neunundneunzig","nueve y noventa"],["100","hundert","cien"]],"nota":"Por teléfono muchos alemanes dicen <b>zwo</b> en lugar de <i>zwei</i>, para no confundirlo con <i>drei</i>. Los teléfonos se dictan número por número o en pares: <i>vier-vier-zwo</i>."},{"tipo":"comparar","titulo":"Los números que más se equivocan","malTitulo":"Evita","mal":"<i>eins</i>und<i>zwanzig</i> · <i>sechs</i>zehn · <i>sieben</i>zehn · <i>dreizig</i><br>Decir 45 como «cuarenta y cinco»: <i>vierzigfünf</i>","bienTitulo":"Correcto","bien":"<i><b>ein</b>undzwanzig</i> · <i><b>sech</b>zehn</i> · <i><b>sieb</b>zehn</i> · <i><b>dreißig</b></i><br><i><b>fünfundvierzig</b></i>: primero el 5, luego el 40."},{"tipo":"escuchar","rotulo":"Escucha y escribe el número en tu cuaderno","frases":[{"en":"siebenundvierzig","pron":"zíben-unt-fírtsij","es":"47"},{"en":"dreiundachtzig","pron":"drái-unt-ájtsij","es":"83"},{"en":"sechsundsechzig","pron":"zeks-unt-zéjtsij","es":"66"},{"en":"zwölf","pron":"tsvölf","es":"12"},{"en":"Meine Nummer ist vier-vier-zwo, drei-eins-acht.","pron":"máine núma ist fía-fía-tsvo, drai-ains-ajt","es":"Mi número es 442 318…"}]},{"tipo":"practica","rotulo":"¿Qué número es?","preguntas":[{"p":"<i>vierundfünfzig</i> es…","ops":["45","54","44"],"correcta":1,"explica":"Primero la unidad (<i>vier</i> = 4), luego la decena (<i>fünfzig</i> = 50): <b>54</b>."},{"p":"¿Cómo se escribe 30?","ops":["dreizig","dreizehn","dreißig"],"correcta":2},{"p":"¿Cómo se dice 16?","ops":["sechzehn","sechszehn","sechzig"],"correcta":0},{"p":"En el teléfono te dictan <i>zwo</i>. Es el número…","ops":["3","2","12"],"correcta":1},{"p":"¿Cómo se dice 71?","ops":["siebzigeins","einssiebzig","einundsiebzig"],"correcta":2}]},{"tipo":"completar","rotulo":"Haz la cuenta y escribe el resultado con letra","voz":true,"items":[{"frase":"Zehn plus zehn ist ___.","resp":["zwanzig"],"es":"10 + 10 = 20"},{"frase":"Zwanzig plus eins ist ___.","resp":["einundzwanzig"],"es":"20 + 1 = 21"},{"frase":"Drei mal zehn ist ___.","resp":["dreißig","dreissig"],"es":"3 × 10 = 30"},{"frase":"Fünfzig plus fünf ist ___.","resp":["fünfundfünfzig","fuenfundfuenfzig"],"es":"50 + 5 = 55"},{"frase":"Hundert minus eins ist ___.","resp":["neunundneunzig"],"es":"100 − 1 = 99"}]},{"tipo":"clave","items":["0-12 se memorizan; 13-19 llevan <b>-zehn</b>; las decenas llevan <b>-zig</b> (salvo <i>dreißig</i>).","Del 21 al 99: <b>primero la unidad</b>, luego la decena: <i>fünfundvierzig</i> = 45.","<i>ein</i>undzwanzig, <i>sech</i>zehn, <i>sieb</i>zehn: pierden letras.","Por teléfono, <b>zwo</b> = 2."]}],"c-aleman-a1-m2-l2":[{"tipo":"texto","texto":"<b>Haben</b> significa «tener» y es el segundo verbo más usado del alemán. Lo necesitas para tu familia (<i>Ich habe zwei Kinder</i>), tu tiempo (<i>Hast du Zeit?</i>) o si tienes hambre (<i>Ich habe Hunger</i>). Pero ojo con una trampa enorme: <b>la edad no se dice con haben</b>, sino con <b>sein</b>: <i>Ich <b>bin</b> 30 Jahre alt</i>, literalmente «soy de 30 años de edad»."},{"tipo":"tabla","titulo":"Haben en presente","voz":true,"colVoz":0,"encabezados":["Alemán","Se lee aprox.","Español"],"filas":[["ich habe","ij hábe","yo tengo"],["du hast","du hast","tú tienes"],["er / sie / es hat","er / zi / es hat","él / ella tiene"],["wir haben","via háben","nosotros tenemos"],["ihr habt","ía hapt","ustedes tienen (de confianza)"],["sie / Sie haben","zi háben","ellos tienen · usted tiene"]],"nota":"Frases que usarás mucho: <i>Ich habe eine Frage</i> (tengo una pregunta), <i>Ich habe keine Zeit</i> (no tengo tiempo), <i>Wir haben Durst</i> (tenemos sed)."},{"tipo":"comparar","titulo":"Tener años, tener frío: calcos del español","malTitulo":"Evita","mal":"<i>Ich habe 30 Jahre.</i><br><i>Ich habe kalt.</i>","bienTitulo":"Correcto","bien":"<i>Ich <b>bin</b> 30 Jahre alt.</i> — Pregunta: <i>Wie alt bist du? / Wie alt sind Sie?</i><br><i><b>Mir ist</b> kalt.</i> (tengo frío) · <i>Mir ist warm.</i> (tengo calor)"},{"tipo":"dialogo","titulo":"Diálogo — Registro en una empresa alemana en Querétaro","lineas":[{"quien":"Frau Braun","en":"Wie ist Ihr Name, bitte?","es":"¿Cuál es su nombre, por favor?"},{"quien":"Luis","en":"Luis Hernández.","es":"Luis Hernández."},{"quien":"Frau Braun","en":"Wie alt sind Sie, Herr Hernández?","es":"¿Cuántos años tiene, señor Hernández?"},{"quien":"Luis","en":"Ich bin zweiunddreißig Jahre alt.","es":"Tengo treinta y dos años."},{"quien":"Frau Braun","en":"Haben Sie Kinder?","es":"¿Tiene hijos?"},{"quien":"Luis","en":"Ja, ich habe zwei Kinder, eine Tochter und einen Sohn.","es":"Sí, tengo dos hijos: una hija y un hijo."},{"quien":"Frau Braun","en":"Und wie ist Ihre Handynummer?","es":"¿Y cuál es su número de celular?"},{"quien":"Luis","en":"Vier-vier-zwo, drei-eins-acht, sieben-sieben-sechs-fünf.","es":"442 318 7765."},{"quien":"Frau Braun","en":"Danke. Haben Sie noch eine Frage?","es":"Gracias. ¿Tiene alguna otra pregunta?"},{"quien":"Luis","en":"Nein, danke. Alles klar!","es":"No, gracias. ¡Todo claro!"}]},{"tipo":"completar","rotulo":"¿haben o sein?","voz":true,"items":[{"frase":"Ich ___ zwei Kinder.","resp":["habe"],"es":"Tengo dos hijos."},{"frase":"___ du heute Zeit?","resp":["Hast"],"es":"¿Tienes tiempo hoy?"},{"frase":"Er ___ eine Schwester.","resp":["hat"],"es":"Él tiene una hermana."},{"frase":"Wir ___ Hunger.","resp":["haben"],"es":"Tenemos hambre."},{"frase":"Ihr ___ ein schönes Haus.","resp":["habt"],"es":"Ustedes tienen una casa bonita."},{"frase":"Ich ___ dreißig Jahre alt.","resp":["bin"],"es":"Tengo treinta años. (¡cuidado!)"}]},{"tipo":"practica","rotulo":"Elige la opción correcta","preguntas":[{"p":"«¿Cuántos años tienes?»","ops":["Wie viele Jahre hast du?","Wie alt bist du?","Wie alt hast du?"],"correcta":1},{"p":"«Tengo frío»","ops":["Ich habe kalt.","Ich bin kalt.","Mir ist kalt."],"correcta":2,"explica":"<i>Ich bin kalt</i> significaría «soy una persona fría»."},{"p":"Frau Braun ___ eine Frage.","ops":["hat","habt","hast"],"correcta":0},{"p":"«¿Tiene usted tiempo?»","ops":["Hast du Zeit?","Haben Sie Zeit?","Habt Sie Zeit?"],"correcta":1},{"p":"<i>Ich habe keine Zeit</i> significa…","ops":["No tengo tiempo.","Tengo mucho tiempo.","¿Qué hora es?"],"correcta":0}]},{"tipo":"clave","items":["<b>haben</b>: <i>ich habe, du hast, er hat, wir haben, ihr habt, sie/Sie haben</i>.","La edad va con <b>sein</b>: <i>Ich bin 30 Jahre alt</i>.","Frío y calor: <i>Mir ist kalt / warm</i>.","<i>Ich habe Hunger / Durst / Zeit / eine Frage.</i>"]}],"c-aleman-a1-m2-l3":[{"tipo":"texto","texto":"Casi todos los países van sin artículo: <i>Ich komme aus Mexiko, aus Deutschland, aus Kanada</i>. Unos pocos lo llevan: <i>aus <b>der</b> Schweiz</i> (Suiza), <i>aus <b>den</b> USA</i>. Para el femenino de nacionalidades y profesiones, la regla es muy sencilla: <b>se agrega -in</b>: <i>Lehrer → Lehrerin</i>. A veces la vocal gana diéresis: <i>Arzt → Ärztin</i>, <i>Koch → Köchin</i>. La gran excepción: <i>Deutscher</i> (alemán) y <i>Deutsche</i> (alemana). Recuerda: sin artículo, <i>Ich bin Ingenieurin</i>."},{"tipo":"tabla","titulo":"Países y nacionalidades","voz":true,"colVoz":0,"encabezados":["País","Él es…","Ella es…","Español"],"filas":[["Mexiko","Mexikaner","Mexikanerin","México"],["Deutschland","Deutscher","Deutsche","Alemania"],["Österreich","Österreicher","Österreicherin","Austria"],["die Schweiz","Schweizer","Schweizerin","Suiza"],["Spanien","Spanier","Spanierin","España"],["Kolumbien","Kolumbianer","Kolumbianerin","Colombia"],["die USA","Amerikaner","Amerikanerin","Estados Unidos"],["Kanada","Kanadier","Kanadierin","Canadá"]]},{"tipo":"tabla","titulo":"Profesiones","voz":true,"colVoz":1,"encabezados":["Español","Él","Ella"],"filas":[["maestro / maestra","Lehrer","Lehrerin"],["ingeniero / ingeniera","Ingenieur","Ingenieurin"],["médico / médica","Arzt","Ärztin"],["cocinero / cocinera","Koch","Köchin"],["mesero / mesera","Kellner","Kellnerin"],["vendedor / vendedora","Verkäufer","Verkäuferin"],["enfermero / enfermera","Krankenpfleger","Krankenpflegerin"],["técnico / técnica","Techniker","Technikerin"],["estudiante","Student","Studentin"],["jubilado / jubilada","Rentner","Rentnerin"]],"nota":"Para preguntar: <i>Was sind Sie von Beruf?</i> (¿A qué se dedica?) o, entre amigos, <i>Was machst du beruflich?</i>"},{"tipo":"comparar","titulo":"Falsos amigos del trabajo","malTitulo":"Evita pensar que…","mal":"<i>Chef</i> es el cocinero.<br><i>Rente</i> es lo que pagas por tu depa.<br><i>Gymnasium</i> es el gimnasio.","bienTitulo":"En realidad…","bien":"<i>der <b>Chef</b></i> = el jefe. El cocinero es <i>der Koch</i>.<br><i>die <b>Rente</b></i> = la pensión de jubilación; la renta del depa es <i>die Miete</i>.<br><i>das <b>Gymnasium</b></i> = la prepa (escuela); el gimnasio es <i>das Fitnessstudio</i>."},{"tipo":"practica","rotulo":"Elige la opción correcta","preguntas":[{"p":"«Ella es maestra»","ops":["Sie ist eine Lehrer.","Sie ist Lehrerin.","Sie ist Lehrer."],"correcta":1},{"p":"«Soy de Suiza»","ops":["Ich komme aus der Schweiz.","Ich komme aus Schweiz.","Ich bin von Schweiz."],"correcta":0},{"p":"Tu colega dice <i>Mein Chef ist Deutscher</i>. Habla de…","ops":["su cocinero","su jefe","su maestro"],"correcta":1},{"p":"El femenino de <i>Arzt</i> es…","ops":["Arztin","Ärztin","Ärzte"],"correcta":1,"explica":"Se agrega <b>-in</b> y la a gana diéresis: <b>Ärztin</b>."},{"p":"<i>Mein Opa ist Rentner.</i> Tu abuelo…","ops":["renta cuartos","es corredor","está jubilado"],"correcta":2}]},{"tipo":"relacionar","rotulo":"Relaciona cada profesión","voz":true,"pares":[["Köchin","cocinera"],["Kellner","mesero"],["Ärztin","médica"],["Verkäufer","vendedor"],["Krankenpflegerin","enfermera"],["Rentner","jubilado"]]},{"tipo":"pronunciar","rotulo":"Di a qué te dedicas","frases":[{"en":"Ich bin Ingenieurin.","pron":"ij bin inyeniörin","es":"Soy ingeniera."},{"en":"Ich bin Techniker von Beruf.","pron":"ij bin téjnika fon berúf","es":"Soy técnico de profesión."},{"en":"Mein Chef kommt aus Österreich.","pron":"main shef komt aus östaraij","es":"Mi jefe es de Austria."},{"en":"Was sind Sie von Beruf?","pron":"vas zint zi fon berúf","es":"¿A qué se dedica usted?"}]},{"tipo":"clave","items":["Femenino con <b>-in</b>: <i>Lehrerin, Ingenieurin, Ärztin, Köchin</i>.","Profesión y nacionalidad <b>sin artículo</b>: <i>Ich bin Kellnerin</i>.","<i>aus der Schweiz, aus den USA</i>; casi todos los demás países sin artículo.","<b>Chef</b> = jefe · <b>Rente</b> = pensión · <b>Gymnasium</b> = prepa."]}],"c-aleman-a1-m2-l4":[{"tipo":"texto","texto":"El alemán tiene tres géneros: <b>der</b> (masculino), <b>die</b> (femenino) y <b>das</b> (neutro). Respira: hasta los alemanes aprendieron cada palabra con su artículo, y nadie espera que aciertes siempre desde el principio. Tres consejos que sí funcionan:<br><b>1)</b> Aprende cada sustantivo <b>con su artículo</b>, como si fuera parte de la palabra: no «Tisch», sino «der Tisch».<br><b>2)</b> Usa las <b>terminaciones</b> de la tabla: aciertan en la gran mayoría de los casos.<br><b>3)</b> En plural es fácil: siempre <b>die</b>.<br>Y el artículo indefinido es <b>ein</b> para der y das, y <b>eine</b> para die: <i>ein Tisch, ein Auto, eine Tasche</i>."},{"tipo":"tabla","titulo":"Pistas que casi nunca fallan","voz":true,"colVoz":2,"encabezados":["Artículo","Pista","Ejemplos"],"filas":[["die","-ung, -heit, -keit, -schaft, -ion, -tät","die Zeitung, die Freiheit, die Information, die Universität"],["die","casi todas las que terminan en -e","die Tasche, die Straße, die Lampe"],["das","diminutivos en -chen y -lein","das Mädchen, das Brötchen"],["das","-um y -ment","das Museum, das Zentrum, das Dokument"],["der","días, meses y estaciones","der Montag, der Mai, der Sommer"],["der","-ling y -ismus","der Frühling, der Tourismus"],["el de la última palabra","palabras compuestas (Kaffee + Maschine)","die Kaffeemaschine, das Hotelzimmer"]],"nota":"<i>das Mädchen</i> (la niña) es neutro por la terminación <i>-chen</i>, no por la niña. Excepciones en -e que sí son der: <i>der Name, der Käse, der Junge</i>."},{"tipo":"comparar","titulo":"No copies el género del español","malTitulo":"Evita","mal":"<i>der Sonne</i> (porque «el sol»)<br><i>die Mond</i> (porque «la luna»)<br><i>die Wasser</i> (porque «el agua» es femenino)","bienTitulo":"Correcto","bien":"<i><b>die</b> Sonne</i> = el sol<br><i><b>der</b> Mond</i> = la luna<br><i><b>das</b> Wasser</i> = el agua"},{"tipo":"practica","rotulo":"¿Der, die o das?","preguntas":[{"p":"___ Zeitung (el periódico)","ops":["der","die","das"],"correcta":1,"explica":"Termina en <b>-ung</b>: siempre <b>die</b>."},{"p":"___ Brötchen (el bolillo)","ops":["der","die","das"],"correcta":2,"explica":"Termina en <b>-chen</b>: siempre <b>das</b>."},{"p":"___ Montag (el lunes)","ops":["der","die","das"],"correcta":0},{"p":"___ Kaffeemaschine (la cafetera)","ops":["der","die","das"],"correcta":1,"explica":"Manda la última palabra: <i>die Maschine</i>."},{"p":"___ Museum (el museo)","ops":["der","die","das"],"correcta":2}]},{"tipo":"completar","rotulo":"¿ein o eine?","voz":true,"items":[{"frase":"Das ist ___ Tisch.","resp":["ein"],"es":"Es una mesa. (der Tisch)"},{"frase":"Das ist ___ Tasche.","resp":["eine"],"es":"Es una bolsa. (die Tasche)"},{"frase":"Das ist ___ Handy.","resp":["ein"],"es":"Es un celular. (das Handy)"},{"frase":"Das ist ___ Zeitung.","resp":["eine"],"es":"Es un periódico. (die Zeitung)"},{"frase":"Das ist ___ Brötchen.","resp":["ein"],"es":"Es un bolillo. (das Brötchen)"}]},{"tipo":"tarjetas","rotulo":"Palabras con su artículo","voz":true,"vozEn":"reverso","instruccion":"Di la palabra en alemán con su artículo antes de voltear.","tarjetas":[{"frente":"la calle","reverso":"die Straße","ej":"Die Straße ist lang."},{"frente":"el celular","reverso":"das Handy","ej":"Das Handy ist neu."},{"frente":"la mesa","reverso":"der Tisch","ej":"Der Tisch ist groß."},{"frente":"la niña","reverso":"das Mädchen","ej":"Das Mädchen heißt Lena."},{"frente":"la información","reverso":"die Information","ej":"Die Information ist wichtig."},{"frente":"el verano","reverso":"der Sommer","ej":"Der Sommer ist warm."}]},{"tipo":"clave","items":["Aprende cada sustantivo <b>con su artículo</b>.","<b>die</b>: -ung, -heit, -keit, -ion y casi todas en -e · <b>das</b>: -chen, -um · <b>der</b>: días, meses, estaciones.","En las palabras compuestas manda la última.","<b>ein</b> para der y das; <b>eine</b> para die. El plural siempre es <b>die</b>."]}],"c-aleman-a1-m2-l5":[{"tipo":"texto","texto":"Esta es <b>la regla más importante del curso</b>, y es más fácil de lo que parece: en una frase afirmativa, <b>el verbo conjugado siempre ocupa el segundo lugar</b>. Lo que va primero puede cambiar; el verbo no se mueve:<br><i><b>Ich</b> arbeite heute in Puebla.</i><br><i><b>Heute</b> arbeite ich in Puebla.</i><br><i><b>In Puebla</b> arbeite ich heute.</i><br>Fíjate: si empiezas con <i>heute</i>, el <i>ich</i> se pasa <b>después</b> del verbo. En las preguntas con palabra W, el verbo también va en segundo lugar (<i>Wo <b>wohnst</b> du?</i>). En las preguntas de sí o no, el verbo va <b>primero</b>: <i><b>Hast</b> du Zeit?</i>"},{"tipo":"tabla","titulo":"Las palabras W","voz":true,"colVoz":2,"encabezados":["Alemán","Español","Ejemplo"],"filas":[["wer?","¿quién?","Wer ist das?"],["was?","¿qué?","Was machst du?"],["wo?","¿dónde?","Wo wohnst du?"],["woher?","¿de dónde?","Woher kommen Sie?"],["wohin?","¿adónde?","Wohin fährst du?"],["wie?","¿cómo?","Wie heißen Sie?"],["wann?","¿cuándo?","Wann kommst du?"],["wie viel?","¿cuánto?","Wie viel kostet das?"],["warum?","¿por qué?","Warum lernst du Deutsch?"]],"nota":"Si sabes inglés, cuidado: <b>wer</b> = quién (no «where») y <b>wo</b> = dónde."},{"tipo":"comparar","titulo":"El verbo no se mueve del segundo lugar","malTitulo":"Evita","mal":"<i>Heute ich arbeite.</i><br><i>Wo du wohnst?</i><br><i>Am Montag ich lerne Deutsch.</i>","bienTitulo":"Correcto","bien":"<i>Heute <b>arbeite</b> ich.</i><br><i>Wo <b>wohnst</b> du?</i><br><i>Am Montag <b>lerne</b> ich Deutsch.</i>"},{"tipo":"dialogo","titulo":"Diálogo — Primer día de capacitación en Alemania","lineas":[{"quien":"Lukas","en":"Hallo! Ich bin Lukas. Wie heißt du?","es":"¡Hola! Soy Lukas. ¿Cómo te llamas?"},{"quien":"Mariana","en":"Ich heiße Mariana. Freut mich!","es":"Me llamo Mariana. ¡Mucho gusto!"},{"quien":"Lukas","en":"Woher kommst du?","es":"¿De dónde eres?"},{"quien":"Mariana","en":"Aus Mexiko. Ich wohne in Puebla.","es":"De México. Vivo en Puebla."},{"quien":"Lukas","en":"Und was machst du hier?","es":"¿Y qué haces aquí?"},{"quien":"Mariana","en":"Ich bin Technikerin. Diese Woche mache ich hier eine Schulung.","es":"Soy técnica. Esta semana tomo aquí una capacitación."},{"quien":"Lukas","en":"Super! Wann fliegst du zurück?","es":"¡Qué bien! ¿Cuándo regresas (en avión)?"},{"quien":"Mariana","en":"Am Samstag.","es":"El sábado."}]},{"tipo":"ordenar","rotulo":"Arma la frase con el verbo en segundo lugar","voz":true,"items":[{"frase":"Heute arbeite ich in Puebla.","es":"Hoy trabajo en Puebla. (empieza con «Heute»)","otras":["Ich arbeite heute in Puebla.","In Puebla arbeite ich heute."],"explica":"El verbo <b>arbeite</b> queda en segundo lugar."},{"frase":"Wo wohnst du?","es":"¿Dónde vives?"},{"frase":"Woher kommen Sie?","es":"¿De dónde es usted?"},{"frase":"Hast du morgen Zeit?","es":"¿Tienes tiempo mañana?","explica":"Pregunta de sí o no: el verbo va <b>primero</b>."},{"frase":"Am Montag lerne ich Deutsch.","es":"El lunes estudio alemán. (empieza con «Am Montag»)","otras":["Ich lerne am Montag Deutsch."],"explica":"<i>Am Montag</i> ocupa el primer lugar; el verbo, el segundo."}]},{"tipo":"practica","rotulo":"¿Qué palabra W necesitas?","preguntas":[{"p":"___ kommst du? — Aus Monterrey.","ops":["Woher","Wo","Wer"],"correcta":0},{"p":"___ ist das? — Das ist mein Chef.","ops":["Was","Wer","Wie"],"correcta":1},{"p":"___ kostet das? — Zehn Euro.","ops":["Wann","Warum","Wie viel"],"correcta":2},{"p":"___ kommt der Bus? — Um acht Uhr.","ops":["Wann","Wo","Wohin"],"correcta":0},{"p":"¿Cuál frase está bien?","ops":["Morgen ich habe Zeit.","Morgen habe ich Zeit.","Morgen Zeit ich habe."],"correcta":1,"explica":"El verbo <b>habe</b> va en segundo lugar."}]},{"tipo":"clave","items":["Regla de oro: el verbo conjugado va en <b>segundo lugar</b>.","Si empiezas con <i>heute, morgen, am Montag…</i>, el sujeto va <b>después</b> del verbo.","Pregunta W: palabra W + verbo + sujeto. Pregunta de sí o no: el verbo va primero.","<b>wer</b> = quién · <b>wo</b> = dónde · <b>woher</b> = de dónde."]}],"c-aleman-a1-m3-l1":[{"tipo":"texto","texto":"Buena noticia: la mayoría de los verbos alemanes siguen <b>un solo modelo</b>. Quitas el <b>-en</b> del infinitivo y agregas las terminaciones <b>-e, -st, -t, -en, -t, -en</b>. Con eso ya conjugas <i>wohnen</i> (vivir), <i>lernen</i> (aprender, estudiar), <i>machen</i> (hacer), <i>kochen</i> (cocinar), <i>spielen</i> (jugar), <i>trinken</i> (tomar), <i>kaufen</i> (comprar), <i>kommen</i> (venir) y <i>gehen</i> (ir a pie). Si la raíz termina en <b>-t</b> o <b>-d</b>, como <i>arbeiten</i>, se agrega una <b>e</b> para que se pueda pronunciar: <i>du arbeit<b>e</b>st, er arbeit<b>e</b>t</i>.<br>Otra buena noticia: el alemán <b>no tiene</b> «estoy trabajando». <i>Ich arbeite</i> significa «trabajo» y también «estoy trabajando»."},{"tipo":"tabla","titulo":"Dos verbos modelo","voz":true,"colVoz":1,"encabezados":["Persona","wohnen (vivir)","arbeiten (trabajar)"],"filas":[["ich","ich wohne","ich arbeite"],["du","du wohnst","du arbeitest"],["er / sie / es","er wohnt","er arbeitet"],["wir","wir wohnen","wir arbeiten"],["ihr","ihr wohnt","ihr arbeitet"],["sie / Sie","sie wohnen","sie arbeiten"]],"nota":"Algunos verbos cambian la vocal, pero <b>solo con du y er/sie/es</b>: <i>fahren → du fährst, er fährt</i>; <i>essen → du isst, er isst</i>; <i>sprechen → du sprichst, er spricht</i>; <i>lesen → du liest, er liest</i>. Los demás, normales."},{"tipo":"comparar","titulo":"Errores típicos al conjugar","malTitulo":"Evita","mal":"<i>Ich wohnen in León.</i> (dejar el infinitivo)<br><i>Er arbeit viel.</i><br><i>Ich bin arbeiten.</i> (calco de «estoy trabajando»)","bienTitulo":"Correcto","bien":"<i>Ich <b>wohne</b> in León.</i><br><i>Er <b>arbeitet</b> viel.</i><br><i>Ich <b>arbeite</b>.</i> o <i>Ich arbeite gerade.</i> (ahorita estoy trabajando)"},{"tipo":"escuchar","rotulo":"Escucha frases de todos los días","frases":[{"en":"Ich wohne in León und arbeite in Silao.","pron":"ij vóne in león unt árbaite in silao","es":"Vivo en León y trabajo en Silao."},{"en":"Was machst du am Abend?","pron":"vas majst du am ábent","es":"¿Qué haces en la noche?"},{"en":"Meine Frau kocht sehr gut.","pron":"máine frau kojt zea gut","es":"Mi esposa cocina muy bien."},{"en":"Wir lernen Deutsch.","pron":"via lérnen doich","es":"Estudiamos alemán."},{"en":"Er spricht Spanisch und Englisch.","pron":"er shprijt shpánish unt énglish","es":"Él habla español e inglés."}]},{"tipo":"practica","rotulo":"Elige la forma correcta","preguntas":[{"p":"Du ___ in Monterrey.","ops":["wohne","wohnst","wohnt"],"correcta":1},{"p":"Maria ___ bei Siemens.","ops":["arbeitet","arbeit","arbeiten"],"correcta":0,"explica":"Raíz en <b>-t</b>: se agrega una <b>e</b>: <i>arbeit<b>e</b>t</i>."},{"p":"Wir ___ Kaffee.","ops":["trinkt","trinke","trinken"],"correcta":2},{"p":"«¿Hablas alemán?»","ops":["Sprechst du Deutsch?","Sprichst du Deutsch?","Sprecht du Deutsch?"],"correcta":1,"explica":"<i>sprechen</i> cambia la vocal con <b>du</b>: <i>du sprichst</i>."},{"p":"«Estoy comiendo»","ops":["Ich bin essen.","Ich esse.","Ich essen."],"correcta":1}]},{"tipo":"completar","rotulo":"Conjuga el verbo","voz":true,"items":[{"frase":"Ich ___ in Guadalajara.","resp":["wohne"],"es":"Vivo en Guadalajara. (wohnen)"},{"frase":"Er ___ Deutsch.","resp":["lernt"],"es":"Él estudia alemán. (lernen)"},{"frase":"Ihr ___ viel.","resp":["arbeitet"],"es":"Ustedes trabajan mucho. (arbeiten)"},{"frase":"Was ___ du heute?","resp":["machst"],"es":"¿Qué haces hoy? (machen)"},{"frase":"Maria ___ gern Tacos.","resp":["isst"],"es":"A María le gusta comer tacos. (essen)"},{"frase":"Wir ___ aus Mexiko.","resp":["kommen"],"es":"Somos de México. (kommen)"}]},{"tipo":"clave","items":["Terminaciones: <i>ich -e, du -st, er -t, wir -en, ihr -t, sie/Sie -en</i>.","Raíz en -t o -d: <i>du arbeitest, er arbeitet</i>.","Algunos cambian la vocal solo con du y er: <i>fährst, isst, sprichst</i>.","No existe «estoy trabajando»: <i>Ich arbeite</i> sirve para las dos cosas."]}],"c-aleman-a1-m3-l2":[{"tipo":"texto","texto":"Algunos verbos alemanes vienen en dos piezas: un <b>prefijo</b> y el verbo. En el diccionario aparecen juntos (<i>aufstehen</i>, levantarse), pero en la frase <b>se separan</b>: el verbo conjugado va en su lugar de siempre, el segundo, y el prefijo se va <b>hasta el final</b>:<br><i>Ich <b>stehe</b> um sechs Uhr <b>auf</b>.</i><br>Piensa en una cajita: el verbo abre la frase y el prefijo la cierra. Todo lo demás va en medio."},{"tipo":"tabla","titulo":"Verbos separables para tu rutina","voz":true,"colVoz":2,"encabezados":["Verbo","Español","Ejemplo"],"filas":[["aufstehen","levantarse","Ich stehe um sechs Uhr auf."],["anfangen","empezar","Die Arbeit fängt um sieben Uhr an."],["einkaufen","hacer las compras","Am Samstag kaufe ich ein."],["anrufen","llamar por teléfono","Ich rufe meine Mutter an."],["fernsehen","ver la tele","Abends sehe ich fern."],["aufräumen","recoger, ordenar","Am Sonntag räume ich auf."],["mitkommen","venir con alguien","Kommst du mit?"]],"nota":"Los prefijos más comunes: <b>auf-, an-, ein-, mit-, fern-, aus-, zurück-</b>. Si ves uno de ellos, busca su pareja al final de la frase."},{"tipo":"comparar","titulo":"El prefijo va al final","malTitulo":"Evita","mal":"<i>Ich aufstehe um sechs Uhr.</i><br><i>Ich rufe an meine Mutter.</i>","bienTitulo":"Correcto","bien":"<i>Ich <b>stehe</b> um sechs Uhr <b>auf</b>.</i><br><i>Ich <b>rufe</b> meine Mutter <b>an</b>.</i>"},{"tipo":"escuchar","rotulo":"La rutina de Rosa, operadora en una planta de Puebla","frases":[{"en":"Ich stehe um fünf Uhr auf.","pron":"ij shtée um fünf ua auf","es":"Me levanto a las cinco."},{"en":"Um sechs Uhr fahre ich mit dem Bus zur Arbeit.","pron":"um zeks ua fáre ij mit dem bus tsua árbait","es":"A las seis me voy en camión al trabajo."},{"en":"Die Arbeit fängt um sieben Uhr an.","pron":"di árbait fengt um zíben ua an","es":"El trabajo empieza a las siete."},{"en":"Nach der Arbeit kaufe ich ein.","pron":"naj dea árbait káufe ij ain","es":"Después del trabajo hago las compras."},{"en":"Abends sehe ich fern und rufe meine Schwester an.","pron":"ábents zée ij fern unt rúfe máine shvésta an","es":"En la noche veo la tele y le llamo a mi hermana."}]},{"tipo":"ordenar","rotulo":"Arma la frase: el prefijo va al final","voz":true,"items":[{"frase":"Ich stehe um sechs Uhr auf.","es":"Me levanto a las seis.","otras":["Um sechs Uhr stehe ich auf."]},{"frase":"Die Arbeit fängt um sieben Uhr an.","es":"El trabajo empieza a las siete.","otras":["Um sieben Uhr fängt die Arbeit an."]},{"frase":"Am Samstag kaufe ich ein.","es":"El sábado hago las compras.","otras":["Ich kaufe am Samstag ein."]},{"frase":"Kommst du mit?","es":"¿Vienes (conmigo)?"}]},{"tipo":"practica","rotulo":"Elige la frase correcta","preguntas":[{"p":"«Veo la tele en la noche»","ops":["Abends fernsehe ich.","Abends sehe ich fern.","Abends ich sehe fern."],"correcta":1},{"p":"«Le llamo a mi jefe»","ops":["Ich rufe meinen Chef an.","Ich anrufe meinen Chef.","Ich rufe an meinen Chef."],"correcta":0},{"p":"En <i>Wir räumen heute auf</i>, el verbo del diccionario es…","ops":["räumen","heuteräumen","aufräumen"],"correcta":2,"explica":"Junta el verbo con el prefijo del final: <b>aufräumen</b>."},{"p":"«¿A qué hora empieza el curso?»","ops":["Wann anfängt der Kurs?","Wann fängt der Kurs an?","Wann der Kurs fängt an?"],"correcta":1}]},{"tipo":"clave","items":["Verbos separables: el verbo en <b>segundo lugar</b> y el prefijo <b>al final</b>.","<i>aufstehen, anfangen, einkaufen, anrufen, fernsehen, aufräumen, mitkommen</i>.","Si ves <i>auf, an, ein, mit, fern</i> al final, júntalo con el verbo para entender.","En preguntas de sí o no, igual: <i>Kommst du <b>mit</b>?</i>"]}],"c-aleman-a1-m3-l3":[{"tipo":"texto","texto":"Para preguntar la hora: <b>Wie spät ist es?</b> o <b>Wie viel Uhr ist es?</b> La respuesta empieza con <b>Es ist…</b> Para decir «a las ocho» se usa <b>um</b>: <i>um acht Uhr</i>. Hay dos sistemas: en trenes, tiendas, trabajo y avisos oficiales se usan las <b>24 horas</b> (<i>siebzehn Uhr zwanzig</i> = 17:20); en la conversación, las 12 horas con <i>Viertel</i>, <i>halb</i>, <i>nach</i> y <i>vor</i>. Y la trampa más famosa: <b>halb</b> mira hacia la hora que viene: <i>halb acht</i> = «media para las ocho» = <b>7:30</b>."},{"tipo":"tabla","titulo":"La hora en la conversación","voz":true,"colVoz":1,"encabezados":["Hora","Alemán","Truco"],"filas":[["8:00","Es ist acht Uhr.","Uhr solo con la hora en punto"],["8:05","Es ist fünf nach acht.","nach = después de"],["8:15","Es ist Viertel nach acht.","Viertel = cuarto"],["8:30","Es ist halb neun.","¡Media para las nueve!"],["8:45","Es ist Viertel vor neun.","vor = antes de"],["8:50","Es ist zehn vor neun.","Como «diez para las nueve»"],["12:00","Es ist zwölf Uhr. Es ist Mittag.","Mittag = mediodía"],["17:20","Es ist siebzehn Uhr zwanzig.","Forma oficial: primero la hora, luego los minutos"]],"nota":"Con las 12 horas se aclara con <i>morgens</i> (de la mañana), <i>nachmittags</i> (de la tarde) o <i>abends</i> (de la noche)."},{"tipo":"comparar","titulo":"La trampa de halb","malTitulo":"Evita","mal":"Oír <i>Wir treffen uns um halb neun</i> y llegar a las 9:30.","bienTitulo":"Correcto","bien":"<i>halb neun</i> = <b>8:30</b>: media hora <b>antes</b> de las nueve.<br>Si tienes duda, pregunta: <i>Also um acht Uhr dreißig?</i>"},{"tipo":"escuchar","rotulo":"Escucha y di qué hora es","frases":[{"en":"Es ist Viertel nach drei.","pron":"es ist fírtel naj drai","es":"Son las 3:15."},{"en":"Es ist halb sieben.","pron":"es ist halp zíben","es":"Son las 6:30."},{"en":"Es ist zehn vor zwölf.","pron":"es ist tsen for tsvölf","es":"Son las 11:50."},{"en":"Der Zug fährt um achtzehn Uhr fünfzehn.","pron":"dea tsuk fert um ájtsen ua fǘnftsen","es":"El tren sale a las 18:15."}]},{"tipo":"practica","rotulo":"¿Qué hora es?","preguntas":[{"p":"<i>Es ist halb elf.</i>","ops":["11:30","10:30","11:00"],"correcta":1,"explica":"<b>halb elf</b> = media hora antes de las once: <b>10:30</b>."},{"p":"<i>Es ist Viertel vor acht.</i>","ops":["7:45","8:15","8:45"],"correcta":0},{"p":"<i>Es ist fünf nach zwei.</i>","ops":["1:55","2:05","2:50"],"correcta":1},{"p":"¿Cómo preguntas la hora?","ops":["Was ist die Stunde?","Wie spät ist es?","Welche Uhr hast du?"],"correcta":1},{"p":"«La reunión es a las diez»","ops":["Das Meeting ist an zehn Uhr.","Das Meeting ist um zehn Uhr.","Das Meeting ist in zehn Uhr."],"correcta":1,"explica":"Para la hora: <b>um</b>."}]},{"tipo":"completar","rotulo":"Completa","voz":true,"items":[{"frase":"Wie ___ ist es?","resp":["spät","spaet"],"es":"¿Qué hora es?"},{"frase":"Es ist ___ nach zehn.","resp":["Viertel"],"es":"Son las 10:15."},{"frase":"Es ist ___ drei.","resp":["halb"],"es":"Son las 2:30."},{"frase":"Es ist zehn ___ acht.","resp":["vor"],"es":"Son las 7:50."},{"frase":"Der Kurs fängt ___ neun Uhr an.","resp":["um"],"es":"El curso empieza a las nueve."}]},{"tipo":"clave","items":["<i>Wie spät ist es? — Es ist…</i> · «a las…» = <b>um</b>.","<b>nach</b> = y (después) · <b>vor</b> = para (antes) · <b>Viertel</b> = cuarto.","<b>halb neun</b> = 8:30, no 9:30.","Horarios oficiales en 24 horas: <i>siebzehn Uhr zwanzig</i>."]}],"c-aleman-a1-m3-l4":[{"tipo":"texto","texto":"Los meses se parecen mucho al español: <i>Januar, Februar, März, April, Mai, Juni, Juli, August, September, Oktober, November, Dezember</i>. Los días de la semana son palabras nuevas, pero todos (menos <i>Mittwoch</i>) terminan en <b>-tag</b>. Y para decir «cuándo» hay un truco de tres palabras:<br><b>am</b> + día: <i>am Montag</i> (el lunes)<br><b>im</b> + mes o estación: <i>im Mai, im Winter</i><br><b>um</b> + hora: <i>um acht Uhr</i><br>Ojo con <b>morgen</b> (mañana, el día siguiente) y <b>der Morgen</b> (la mañana, las primeras horas del día)."},{"tipo":"tabla","titulo":"La semana y las estaciones","voz":true,"colVoz":0,"encabezados":["Alemán","Español"],"filas":[["der Montag","el lunes"],["der Dienstag","el martes"],["der Mittwoch","el miércoles"],["der Donnerstag","el jueves"],["der Freitag","el viernes"],["der Samstag","el sábado"],["der Sonntag","el domingo"],["das Wochenende","el fin de semana"],["der Frühling","la primavera"],["der Sommer","el verano"],["der Herbst","el otoño"],["der Winter","el invierno"],["heute · morgen · gestern","hoy · mañana · ayer"]],"nota":"Con -s al final significa «todos los…»: <i>montags</i> (los lunes), <i>morgens</i> (en las mañanas), <i>abends</i> (en las noches)."},{"tipo":"escuchar","rotulo":"Escucha los meses y un cumpleaños","frases":[{"en":"Januar, Februar, März, April","pron":"yánuar, fébruar, merts, april","es":"enero, febrero, marzo, abril"},{"en":"Mai, Juni, Juli, August","pron":"mai, yúni, yúli, august","es":"mayo, junio, julio, agosto"},{"en":"September, Oktober, November, Dezember","pron":"zeptémba, októba, novémba, detsémba","es":"septiembre, octubre, noviembre, diciembre"},{"en":"Ich habe im Mai Geburtstag.","pron":"ij hábe im mai guebúrtstaak","es":"Mi cumpleaños es en mayo."},{"en":"Am Wochenende arbeite ich nicht.","pron":"am vójenende árbaite ij nijt","es":"El fin de semana no trabajo."}]},{"tipo":"comparar","titulo":"am, im, um: no los cambies por «en»","malTitulo":"Evita","mal":"<i>Ich arbeite in Montag.</i><br><i>Mein Urlaub ist am Juli.</i><br><i>Der Kurs ist in neun Uhr.</i>","bienTitulo":"Correcto","bien":"<i>Ich arbeite <b>am</b> Montag.</i><br><i>Mein Urlaub ist <b>im</b> Juli.</i> (mis vacaciones son en julio)<br><i>Der Kurs ist <b>um</b> neun Uhr.</i>"},{"tipo":"relacionar","rotulo":"Relaciona cada día","voz":true,"pares":[["Dienstag","martes"],["Mittwoch","miércoles"],["Donnerstag","jueves"],["Freitag","viernes"],["Sonntag","domingo"],["gestern","ayer"]]},{"tipo":"completar","rotulo":"¿am, im o um?","voz":true,"items":[{"frase":"Ich habe ___ Juni Geburtstag.","resp":["im"],"es":"Mi cumpleaños es en junio."},{"frase":"___ Freitag gehen wir ins Kino.","resp":["Am"],"es":"El viernes vamos al cine."},{"frase":"Die Arbeit fängt ___ sieben Uhr an.","resp":["um"],"es":"El trabajo empieza a las siete."},{"frase":"___ Winter ist es in Berlin sehr kalt.","resp":["Im"],"es":"En invierno hace mucho frío en Berlín."},{"frase":"Wir sehen uns ___ Montag.","resp":["am"],"es":"Nos vemos el lunes."}]},{"tipo":"clave","items":["<b>am</b> + día · <b>im</b> + mes o estación · <b>um</b> + hora.","Los días terminan en <b>-tag</b>, salvo <i>Mittwoch</i>.","<b>morgen</b> = mañana (el día siguiente) · <b>der Morgen</b> = la mañana.","<i>Ich habe im Mai Geburtstag</i> = mi cumpleaños es en mayo."]}],"c-aleman-a1-m3-l5":[{"tipo":"texto","texto":"Para decir que te gusta <b>hacer</b> algo, el alemán no usa un verbo «gustar»: pones la acción y le agregas <b>gern</b> después del verbo: <i>Ich koche <b>gern</b></i> (me gusta cocinar). Para lo que no te gusta: <b>nicht gern</b>. Si te gusta una <b>cosa</b>, usa <b>mögen</b>: <i>Ich mag Tacos</i>. Para negar hay dos palabras:<br><b>kein / keine</b> niega sustantivos que irían con <i>ein, eine</i> o sin artículo: <i>Ich habe <b>kein</b> Auto. Ich habe <b>keine</b> Zeit.</i><br><b>nicht</b> niega todo lo demás: verbos, adjetivos y cosas con <i>der, die, das, mein</i>: <i>Ich arbeite <b>nicht</b>. Das ist <b>nicht</b> teuer.</i>"},{"tipo":"tabla","titulo":"Gustos y negaciones","voz":true,"colVoz":0,"encabezados":["Alemán","Español"],"filas":[["Ich koche gern.","Me gusta cocinar."],["Ich tanze nicht gern.","No me gusta bailar."],["Ich mag Tacos.","Me gustan los tacos."],["Magst du Fußball?","¿Te gusta el futbol?"],["Ich trinke lieber Tee.","Prefiero tomar té."],["Ich habe kein Auto.","No tengo coche."],["Ich habe keine Kinder.","No tengo hijos."],["Ich arbeite heute nicht.","Hoy no trabajo."],["Das ist nicht mein Handy.","Ese no es mi celular."]],"nota":"<i>mögen</i>: <i>ich mag, du magst, er mag, wir mögen, ihr mögt, sie/Sie mögen</i>."},{"tipo":"comparar","titulo":"¿nicht o kein?","malTitulo":"Evita","mal":"<i>Ich habe nicht Zeit.</i><br><i>Ich habe nicht ein Auto.</i><br><i>Ich nicht arbeite heute.</i>","bienTitulo":"Correcto","bien":"<i>Ich habe <b>keine</b> Zeit.</i><br><i>Ich habe <b>kein</b> Auto.</i><br><i>Ich arbeite heute <b>nicht</b>.</i>"},{"tipo":"comparar","titulo":"Falso amigo: also no es «también»","malTitulo":"Evita pensar que…","mal":"<i>also</i> significa «también», como en inglés.","bienTitulo":"En realidad…","bien":"<i><b>also</b></i> = entonces, o sea, bueno: <i>Also, wir fangen an.</i> (Bueno, empezamos.)<br>«También» es <i><b>auch</b></i>: <i>Ich koche auch gern.</i>"},{"tipo":"dialogo","titulo":"Diálogo — Planes para el fin de semana","lineas":[{"quien":"Sofía","en":"Was machst du gern am Wochenende?","es":"¿Qué te gusta hacer el fin de semana?"},{"quien":"Tim","en":"Ich spiele gern Fußball. Und du?","es":"Me gusta jugar futbol. ¿Y a ti?"},{"quien":"Sofía","en":"Ich spiele nicht gern Fußball, aber ich koche gern.","es":"No me gusta jugar futbol, pero me gusta cocinar."},{"quien":"Tim","en":"Also kochst du am Samstag für uns?","es":"¿Entonces cocinas el sábado para nosotros?"},{"quien":"Sofía","en":"Gern! Magst du scharfes Essen?","es":"¡Con gusto! ¿Te gusta la comida picante?"},{"quien":"Tim","en":"Ja, sehr! Aber ich habe keine Tortillas.","es":"¡Sí, mucho! Pero no tengo tortillas."},{"quien":"Sofía","en":"Kein Problem, ich kaufe ein.","es":"No hay problema, yo hago las compras."}]},{"tipo":"practica","rotulo":"Elige la opción correcta","preguntas":[{"p":"«Me gusta leer»","ops":["Ich lese gern.","Ich gern lese.","Ich mag gern lesen."],"correcta":0},{"p":"«No tengo tiempo»","ops":["Ich habe nicht Zeit.","Ich habe keine Zeit.","Ich nicht habe Zeit."],"correcta":1},{"p":"«El café no está caliente»","ops":["Der Kaffee ist kein heiß.","Der Kaffee ist nicht heiß.","Der Kaffee nicht ist heiß."],"correcta":1,"explica":"Adjetivo = <b>nicht</b>."},{"p":"Tim dice <i>Ich komme auch</i>. <i>auch</i> significa…","ops":["entonces","también","tampoco"],"correcta":1},{"p":"«¿Te gustan los tacos?»","ops":["Magst du Tacos?","Gern du Tacos?","Hast du gern Tacos?"],"correcta":0}]},{"tipo":"completar","rotulo":"gern, nicht, kein o keine","voz":true,"items":[{"frase":"Ich habe ___ Auto.","resp":["kein"],"es":"No tengo coche."},{"frase":"Wir haben ___ Zeit.","resp":["keine"],"es":"No tenemos tiempo."},{"frase":"Ich arbeite heute ___.","resp":["nicht"],"es":"Hoy no trabajo."},{"frase":"Ich tanze sehr ___.","resp":["gern","gerne"],"es":"Me gusta mucho bailar."},{"frase":"Das ist ___ teuer.","resp":["nicht"],"es":"No es caro."}]},{"tipo":"clave","items":["Me gusta hacer algo: verbo + <b>gern</b>. Me gusta algo: <b>mögen</b>.","<b>kein/keine</b> para sustantivos sin artículo o con <i>ein/eine</i>.","<b>nicht</b> para verbos, adjetivos y todo lo demás.","<b>also</b> = entonces, bueno · <b>auch</b> = también. Pasa a la evaluación: necesitas 80%."]}],"c-aleman-a1-m4-l1":[{"tipo":"texto","texto":"Para decir «hay» se usa <b>es gibt</b>, y no cambia aunque sean muchas cosas: <i>Es gibt ein Museum. Es gibt zwei Supermärkte.</i> Para preguntar, se invierte (el verbo va primero): <b>Gibt es hier…?</b> (¿hay por aquí…?). Un detalle que verás a fondo en la lección 4: después de <i>es gibt</i>, las palabras con <b>der</b> cambian <i>ein</i> por <b>einen</b>: <i>der Park → Es gibt <b>einen</b> Park</i>. Con <i>die</i> y <i>das</i> no cambia nada. Para decir que no hay, usa <b>kein</b>: <i>Hier gibt es keine Bank.</i>"},{"tipo":"tabla","titulo":"Lugares de la ciudad","voz":true,"colVoz":0,"encabezados":["Alemán","Español"],"filas":[["der Bahnhof","la estación de tren"],["die Haltestelle","la parada (de camión o tranvía)"],["der Supermarkt","el supermercado"],["die Bäckerei","la panadería"],["die Apotheke","la farmacia"],["die Bank","el banco"],["der Geldautomat","el cajero automático"],["das Krankenhaus","el hospital"],["das Museum","el museo"],["der Park","el parque"],["die Post","la oficina de correos"]],"nota":"<i>Gibt es hier in der Nähe…?</i> = ¿Hay por aquí cerca…? Es la pregunta más útil de toda la lección."},{"tipo":"comparar","titulo":"«Hay» no se dice con haben","malTitulo":"Evita","mal":"<i>Hier hat einen Park.</i><br><i>Es gibt ein Park.</i><br><i>Es geben zwei Museen.</i>","bienTitulo":"Correcto","bien":"<i>Hier <b>gibt es</b> einen Park.</i><br><i>Es gibt <b>einen</b> Park.</i> (der Park)<br><i>Es <b>gibt</b> zwei Museen.</i> (siempre <i>gibt</i>)"},{"tipo":"dialogo","titulo":"Diálogo — En la recepción de un hotel en Múnich","lineas":[{"quien":"Paola","en":"Entschuldigung, gibt es hier in der Nähe eine Apotheke?","es":"Disculpe, ¿hay una farmacia por aquí cerca?"},{"quien":"Rezeptionist","en":"Ja, es gibt eine Apotheke am Marienplatz.","es":"Sí, hay una farmacia en Marienplatz."},{"quien":"Paola","en":"Und gibt es auch einen Supermarkt?","es":"¿Y también hay un supermercado?"},{"quien":"Rezeptionist","en":"Hier gibt es keinen Supermarkt, aber es gibt eine Bäckerei gegenüber.","es":"Aquí no hay supermercado, pero hay una panadería enfrente."},{"quien":"Paola","en":"Super. Und wo ist die nächste U-Bahn-Haltestelle?","es":"Perfecto. ¿Y dónde está la parada de metro más cercana?"},{"quien":"Rezeptionist","en":"Gleich um die Ecke.","es":"Aquí a la vuelta."}]},{"tipo":"relacionar","rotulo":"Relaciona cada lugar","voz":true,"pares":[["der Bahnhof","estación de tren"],["die Haltestelle","parada"],["die Apotheke","farmacia"],["das Krankenhaus","hospital"],["die Bäckerei","panadería"],["der Geldautomat","cajero automático"]]},{"tipo":"completar","rotulo":"Completa","voz":true,"items":[{"frase":"Es ___ hier ein Museum.","resp":["gibt"],"es":"Aquí hay un museo."},{"frase":"Gibt es hier ___ Apotheke?","resp":["eine"],"es":"¿Hay una farmacia por aquí? (die Apotheke)"},{"frase":"Hier gibt es ___ Park.","resp":["einen"],"es":"Aquí hay un parque. (der Park)"},{"frase":"In der Straße gibt es ___ Restaurant.","resp":["ein"],"es":"En la calle hay un restaurante. (das Restaurant)"},{"frase":"Nein, hier gibt es ___ Bank.","resp":["keine"],"es":"No, aquí no hay banco. (die Bank)"}]},{"tipo":"clave","items":["«Hay» = <b>es gibt</b>, en singular y en plural.","Pregunta: <i>Gibt es hier in der Nähe…?</i>","Con palabras <i>der</i>: <i>Es gibt <b>einen</b> Park</i>.","Para decir que no hay: <i>Hier gibt es kein / keine / keinen…</i>"]}],"c-aleman-a1-m4-l2":[{"tipo":"texto","texto":"La pregunta clave es <b>Wie komme ich zum…? / zur…?</b> (¿Cómo llego al…? / ¿a la…?). Usa <b>zum</b> con palabras <i>der</i> y <i>das</i> (<i>zum Bahnhof, zum Museum</i>) y <b>zur</b> con palabras <i>die</i> (<i>zur Post, zur Apotheke</i>). Las respuestas vienen casi siempre con el verbo al principio, porque son instrucciones con <i>Sie</i>: <i><b>Gehen</b> Sie geradeaus</i> (siga derecho). Y empieza siempre con <b>Entschuldigung</b>: es la forma amable de detener a alguien en la calle."},{"tipo":"tabla","titulo":"Frases para moverte","voz":true,"colVoz":0,"encabezados":["Alemán","Español"],"filas":[["Entschuldigung, wie komme ich zum Bahnhof?","Disculpe, ¿cómo llego a la estación?"],["Wo ist die Post, bitte?","¿Dónde está el correo, por favor?"],["Gehen Sie geradeaus.","Siga derecho."],["Gehen Sie nach links / nach rechts.","Vaya a la izquierda / a la derecha."],["Nehmen Sie die erste Straße links.","Tome la primera calle a la izquierda."],["an der Ampel","en el semáforo"],["an der Kreuzung","en el cruce"],["gegenüber","enfrente"],["neben der Bank","al lado del banco"],["Ist das weit?","¿Está lejos?"],["Nur fünf Minuten zu Fuß.","Solo cinco minutos a pie."]],"nota":"Si no entendiste: <i>Können Sie das bitte wiederholen?</i> (¿Puede repetirlo, por favor?) o <i>Langsamer, bitte.</i> (Más despacio, por favor)."},{"tipo":"comparar","titulo":"Cómo detener a alguien en la calle","malTitulo":"Evita","mal":"«¡Oiga!» traducido como <i>Hey, Sie!</i> (suena brusco)<br><i>Wo ist Bahnhof?</i> (sin artículo)","bienTitulo":"Correcto","bien":"<i><b>Entschuldigung</b>, wo ist <b>der</b> Bahnhof?</i><br><i>Entschuldigung, wie komme ich <b>zum</b> Bahnhof?</i><br>Al final: <i>Vielen Dank!</i>"},{"tipo":"dialogo","titulo":"Diálogo — Buscando el museo en Múnich","lineas":[{"quien":"Jorge","en":"Entschuldigung, wie komme ich zum Deutschen Museum?","es":"Disculpe, ¿cómo llego al Museo Alemán?"},{"quien":"Passantin","en":"Gehen Sie hier geradeaus bis zur Ampel.","es":"Siga derecho hasta el semáforo."},{"quien":"Jorge","en":"Bis zur Ampel. Und dann?","es":"Hasta el semáforo. ¿Y luego?"},{"quien":"Passantin","en":"Dann nehmen Sie die zweite Straße rechts. Das Museum ist gegenüber vom Park.","es":"Luego tome la segunda calle a la derecha. El museo está enfrente del parque."},{"quien":"Jorge","en":"Ist das weit?","es":"¿Está lejos?"},{"quien":"Passantin","en":"Nein, nur zehn Minuten zu Fuß.","es":"No, solo diez minutos a pie."},{"quien":"Jorge","en":"Vielen Dank!","es":"¡Muchas gracias!"}]},{"tipo":"practica","rotulo":"¿Entendiste?","preguntas":[{"p":"Te dicen <i>Gehen Sie geradeaus</i>. Tienes que…","ops":["dar la vuelta","seguir derecho","ir a la izquierda"],"correcta":1},{"p":"«¿Cómo llego a la farmacia?» (die Apotheke)","ops":["Wie komme ich zum Apotheke?","Wie komme ich zur Apotheke?","Wie gehe ich Apotheke?"],"correcta":1,"explica":"Palabra <i>die</i> = <b>zur</b>."},{"p":"<i>Die Bank ist gegenüber.</i> El banco está…","ops":["enfrente","a la derecha","muy lejos"],"correcta":0},{"p":"<i>Nehmen Sie die erste Straße links.</i>","ops":["Tome la primera calle a la derecha.","Tome la primera calle a la izquierda.","Cruce la primera calle."],"correcta":1},{"p":"No entendiste la explicación. Dices…","ops":["Was?","Langsamer, bitte.","Tschüss!"],"correcta":1}]},{"tipo":"ordenar","rotulo":"Arma la frase","voz":true,"items":[{"frase":"Wie komme ich zum Bahnhof?","es":"¿Cómo llego a la estación?"},{"frase":"Gehen Sie hier geradeaus.","es":"Siga derecho por aquí."},{"frase":"Nehmen Sie die erste Straße links.","es":"Tome la primera calle a la izquierda."},{"frase":"Die Apotheke ist neben der Bank.","es":"La farmacia está al lado del banco.","otras":["Neben der Bank ist die Apotheke."]}]},{"tipo":"clave","items":["<i>Entschuldigung, wie komme ich <b>zum</b> (der/das) / <b>zur</b> (die)…?</i>","<i>geradeaus</i> = derecho · <i>links</i> = izquierda · <i>rechts</i> = derecha.","<i>an der Ampel, gegenüber, neben</i> = en el semáforo, enfrente, al lado.","Si no entiendes: <i>Langsamer, bitte</i> o <i>Können Sie das bitte wiederholen?</i>"]}],"c-aleman-a1-m4-l3":[{"tipo":"texto","texto":"En español «ir» sirve para todo. En alemán se distingue: <b>gehen</b> es ir <b>a pie</b> y <b>fahren</b> es ir <b>en un vehículo</b> (ojo: <i>du fährst, er fährt</i>). En avión: <b>fliegen</b>. El medio de transporte se dice con <b>mit</b>: <i>mit dem Bus</i> (der Bus, das Auto) y <i>mit der U-Bahn</i> (die Bahn). A pie: <b>zu Fuß</b>.<br>Dato práctico: en muchas ciudades alemanas no hay torniquetes en el metro, pero sí revisores, y viajar sin boleto válido sale caro. Compra el boleto antes de subir y revisa si hay que validarlo en una maquinita."},{"tipo":"tabla","titulo":"Transporte y boletos","voz":true,"colVoz":0,"encabezados":["Alemán","Español"],"filas":[["mit dem Bus","en camión"],["mit der U-Bahn","en metro"],["mit der S-Bahn","en tren urbano"],["mit der Straßenbahn","en tranvía"],["mit dem Zug","en tren"],["mit dem Fahrrad","en bici"],["zu Fuß","a pie"],["die Fahrkarte","el boleto"],["einfach · hin und zurück","sencillo · redondo (ida y vuelta)"],["das Gleis","el andén (la vía)"],["umsteigen","transbordar, cambiar de tren"]],"nota":"Pregunta útil: <i>Wann fährt der nächste Zug nach…?</i> (¿A qué hora sale el próximo tren a…?)."},{"tipo":"comparar","titulo":"Ir a pie o ir en algo","malTitulo":"Evita","mal":"<i>Ich gehe mit dem Bus zur Arbeit.</i><br><i>Ich gehe nach Berlin.</i> (suena a que vas caminando)","bienTitulo":"Correcto","bien":"<i>Ich <b>fahre</b> mit dem Bus zur Arbeit.</i><br><i>Ich <b>fahre</b> mit dem Zug nach Berlin.</i> · <i>Ich <b>fliege</b> nach Berlin.</i><br><i>Ich <b>gehe</b> zu Fuß.</i>"},{"tipo":"dialogo","titulo":"Diálogo — En la estación central de Berlín","lineas":[{"quien":"Carlos","en":"Guten Tag! Eine Fahrkarte nach Potsdam, bitte.","es":"¡Buenas tardes! Un boleto a Potsdam, por favor."},{"quien":"Mitarbeiterin","en":"Einfach oder hin und zurück?","es":"¿Sencillo o redondo?"},{"quien":"Carlos","en":"Hin und zurück, bitte. Was kostet das?","es":"Redondo, por favor. ¿Cuánto cuesta?"},{"quien":"Mitarbeiterin","en":"Das macht neun Euro vierzig.","es":"Son nueve euros con cuarenta."},{"quien":"Carlos","en":"Wann fährt der nächste Zug?","es":"¿A qué hora sale el próximo tren?"},{"quien":"Mitarbeiterin","en":"Um zehn Uhr fünfzehn, von Gleis drei.","es":"A las diez quince, del andén tres."},{"quien":"Carlos","en":"Muss ich umsteigen?","es":"¿Tengo que transbordar?"},{"quien":"Mitarbeiterin","en":"Nein, der Zug fährt direkt.","es":"No, el tren va directo."}]},{"tipo":"practica","rotulo":"Elige la opción correcta","preguntas":[{"p":"«Voy en metro al trabajo»","ops":["Ich gehe mit der U-Bahn zur Arbeit.","Ich fahre in U-Bahn zur Arbeit.","Ich fahre mit der U-Bahn zur Arbeit."],"correcta":2},{"p":"Du ___ mit dem Auto.","ops":["fahrst","fährst","fahrt"],"correcta":1,"explica":"<i>fahren</i> cambia la vocal con du y er: <b>du fährst, er fährt</b>."},{"p":"Quieres un boleto de ida y vuelta. Dices…","ops":["einfach","hin und zurück","umsteigen"],"correcta":1},{"p":"<i>Der Zug fährt von Gleis fünf.</i> El tren sale…","ops":["a las cinco","del andén cinco","en cinco minutos"],"correcta":1},{"p":"«Voy a pie»","ops":["Ich gehe zu Fuß.","Ich fahre zu Fuß.","Ich gehe mit Fuß."],"correcta":0}]},{"tipo":"completar","rotulo":"Completa","voz":true,"items":[{"frase":"Ich fahre mit ___ Bus.","resp":["dem"],"es":"Voy en camión. (der Bus)"},{"frase":"Wir fahren mit ___ U-Bahn.","resp":["der"],"es":"Vamos en metro. (die U-Bahn)"},{"frase":"Er ___ mit dem Zug nach Hamburg.","resp":["fährt","faehrt"],"es":"Él va en tren a Hamburgo."},{"frase":"Wann fährt der ___ Zug nach Potsdam?","resp":["nächste","naechste"],"es":"¿A qué hora sale el próximo tren a Potsdam?"},{"frase":"Muss ich ___?","resp":["umsteigen"],"es":"¿Tengo que transbordar?"}]},{"tipo":"clave","items":["<b>gehen</b> = ir a pie · <b>fahren</b> = ir en vehículo · <b>fliegen</b> = ir en avión.","<i>mit dem</i> (der/das) · <i>mit der</i> (die) · <i>zu Fuß</i>.","<i>einfach</i> = sencillo · <i>hin und zurück</i> = redondo · <i>Gleis</i> = andén.","Compra tu boleto antes de subir: hay revisores y las multas son altas."]}],"c-aleman-a1-m4-l4":[{"tipo":"texto","texto":"«Acusativo» suena a gramática pesada, pero lo que tienes que saber es muy poco. Cuando una cosa o persona <b>recibe la acción</b> (lo que compras, lo que tienes, lo que buscas, lo que hay), las palabras masculinas cambian:<br><b>der → den · ein → einen · kein → keinen · mein → meinen</b><br>Y ya. <b>Con die, das y el plural no cambia nada.</b> Los verbos que más lo piden: <i>haben, brauchen</i> (necesitar), <i>kaufen, nehmen, suchen</i> (buscar), <i>möchten</i> y <i>es gibt</i>. Truco para recordarlo: el señor <i>der</i> es el único que se arregla para salir: se pone la <b>-n</b>."},{"tipo":"tabla","titulo":"Solo el masculino cambia","voz":true,"colVoz":3,"encabezados":["Género","Normal","Recibe la acción","Ejemplo"],"filas":[["masculino","der / ein","den / einen","Ich brauche einen Stift."],["femenino","die / eine","die / eine","Ich kaufe eine Tasche."],["neutro","das / ein","das / ein","Ich nehme das Menü."],["plural","die / –","die / –","Ich habe zwei Kinder."],["negación (masc.)","kein","keinen","Ich habe keinen Hunger."]],"nota":"Compara: <i><b>Der</b> Bus kommt.</i> (el camión hace la acción) · <i>Ich nehme <b>den</b> Bus.</i> (el camión la recibe)."},{"tipo":"comparar","titulo":"No olvides la -n del masculino","malTitulo":"Evita","mal":"<i>Ich habe ein Bruder.</i><br><i>Ich suche der Bahnhof.</i><br><i>Es gibt kein Supermarkt.</i>","bienTitulo":"Correcto","bien":"<i>Ich habe <b>einen</b> Bruder.</i><br><i>Ich suche <b>den</b> Bahnhof.</i><br><i>Es gibt <b>keinen</b> Supermarkt.</i>"},{"tipo":"escuchar","rotulo":"Escucha el acusativo en acción","frases":[{"en":"Ich suche den Bahnhof.","pron":"ij zúje den bánhof","es":"Busco la estación."},{"en":"Haben Sie einen Stadtplan?","pron":"háben zi áinen shtátplan","es":"¿Tiene un mapa de la ciudad?"},{"en":"Wir nehmen den Zug.","pron":"via némen den tsuk","es":"Tomamos el tren."},{"en":"Ich brauche einen Termin.","pron":"ij bráuje áinen termín","es":"Necesito una cita."},{"en":"Ich habe keinen Hunger.","pron":"ij hábe káinen húnga","es":"No tengo hambre."}]},{"tipo":"practica","rotulo":"¿Cambia o no cambia?","preguntas":[{"p":"Ich kaufe ___ Tisch. (der Tisch)","ops":["der","den","die"],"correcta":1},{"p":"Ich kaufe ___ Lampe. (die Lampe)","ops":["die","den","der"],"correcta":0,"explica":"Femenino: <b>no cambia</b>."},{"p":"Hast du ___ Bruder? (der Bruder)","ops":["ein","einen","eine"],"correcta":1},{"p":"Ich nehme ___ Wasser. (das Wasser)","ops":["einen","eine","ein"],"correcta":2,"explica":"Neutro: <b>no cambia</b>."},{"p":"«No tengo coche» (das Auto)","ops":["Ich habe keinen Auto.","Ich habe kein Auto.","Ich habe keine Auto."],"correcta":1}]},{"tipo":"completar","rotulo":"Completa con la forma correcta","voz":true,"items":[{"frase":"Ich brauche ___ Kaffee.","resp":["einen"],"es":"Necesito un café. (der Kaffee)"},{"frase":"Wir suchen ___ Bahnhof.","resp":["den"],"es":"Buscamos la estación. (der Bahnhof)"},{"frase":"Ich habe ___ Schwester.","resp":["eine"],"es":"Tengo una hermana. (die Schwester)"},{"frase":"Er kauft ___ Handy.","resp":["ein"],"es":"Él compra un celular. (das Handy)"},{"frase":"Ich habe ___ Hunger.","resp":["keinen"],"es":"No tengo hambre. (der Hunger)"},{"frase":"Siehst du ___ Park?","resp":["den"],"es":"¿Ves el parque? (der Park)"}]},{"tipo":"clave","items":["Solo el masculino cambia: <b>der → den, ein → einen, kein → keinen</b>.","<i>die, das</i> y el plural se quedan igual.","Lo piden <i>haben, brauchen, kaufen, nehmen, suchen, möchten</i> y <i>es gibt</i>.","<i><b>Der</b> Bus kommt</i>, pero <i>Ich nehme <b>den</b> Bus</i>."]}],"c-aleman-a1-m4-l5":[{"tipo":"texto","texto":"Las panaderías alemanas son famosas: <i>Brötchen</i> (bolillos), <i>Brezeln</i> (pretzels), cientos de panes y pasteles. Para pedir con cortesía usa <b>Ich möchte…</b> (quisiera) o <b>Ich hätte gern…</b> Los precios usan <b>coma</b> para los centavos: 2,50 € se dice <i>zwei Euro fünfzig</i>. Tres costumbres que conviene conocer: en el súper tú empacas <b>rápido</b> y la bolsa se paga; muchas botellas llevan <b>Pfand</b> (un depósito que te regresan al devolverlas); y en algunos negocios pequeños solo aceptan efectivo, así que pregunta: <i>Kann ich mit Karte zahlen?</i>"},{"tipo":"tabla","titulo":"Frases para comprar","voz":true,"colVoz":0,"encabezados":["Alemán","Español"],"filas":[["Was bekommen Sie?","¿Qué va a llevar? · ¿Qué le doy?"],["Ich möchte zwei Brötchen, bitte.","Quisiera dos bolillos, por favor."],["Ich hätte gern eine Brezel.","Quisiera un pretzel."],["Noch etwas?","¿Algo más?"],["Nein, danke. Das ist alles.","No, gracias. Es todo."],["Was kostet das?","¿Cuánto cuesta?"],["Das macht vier Euro fünfzig.","Son cuatro euros con cincuenta."],["Kann ich mit Karte zahlen?","¿Puedo pagar con tarjeta?"],["Brauchen Sie eine Tüte?","¿Necesita bolsa?"]],"nota":"<i>möchten</i>: <i>ich möchte, du möchtest, er/sie möchte</i> (¡sin -t!), <i>wir möchten, ihr möchtet, sie/Sie möchten</i>. Con <i>möchten</i>, las palabras <i>der</i> van en acusativo: <i>Ich möchte <b>einen</b> Kaffee.</i>"},{"tipo":"comparar","titulo":"Falso amigo: bekommen no es «become»","malTitulo":"Evita pensar que…","mal":"<i>Was bekommen Sie?</i> significa «¿En qué se convierte?»<br><i>Ich bekomme müde</i> = me pongo cansado.","bienTitulo":"En realidad…","bien":"<i><b>bekommen</b></i> = recibir. En una tienda, <i>Was bekommen Sie?</i> = ¿Qué le doy? · <i>Ich bekomme zwei Brötchen</i> = Me da dos bolillos.<br>«Ponerse / volverse» es <i><b>werden</b></i>: <i>Ich werde müde.</i>"},{"tipo":"dialogo","titulo":"Diálogo — En una panadería de Múnich","lineas":[{"quien":"Verkäuferin","en":"Guten Morgen! Was bekommen Sie?","es":"¡Buenos días! ¿Qué le doy?"},{"quien":"Ana","en":"Guten Morgen! Ich möchte vier Brötchen und eine Brezel, bitte.","es":"¡Buenos días! Quisiera cuatro bolillos y un pretzel, por favor."},{"quien":"Verkäuferin","en":"Gerne. Noch etwas?","es":"Con gusto. ¿Algo más?"},{"quien":"Ana","en":"Ja, ein Stück Apfelkuchen. Was kostet das?","es":"Sí, una rebanada de pay de manzana. ¿Cuánto cuesta?"},{"quien":"Verkäuferin","en":"Drei Euro zwanzig.","es":"Tres euros con veinte."},{"quien":"Ana","en":"Gut. Das ist alles.","es":"Bien. Es todo."},{"quien":"Verkäuferin","en":"Das macht zusammen sechs Euro dreißig.","es":"En total son seis euros con treinta."},{"quien":"Ana","en":"Kann ich mit Karte zahlen?","es":"¿Puedo pagar con tarjeta?"},{"quien":"Verkäuferin","en":"Ja, natürlich.","es":"Sí, claro."}]},{"tipo":"escuchar","rotulo":"Escucha los precios","frases":[{"en":"Das macht zwei Euro fünfzig.","pron":"das majt tsvai óiro fǘnftsij","es":"Son 2,50 €."},{"en":"Das kostet neunzehn Euro neunundneunzig.","pron":"das kóstet nóintsen óiro nóin-unt-nóintsij","es":"Cuesta 19,99 €."},{"en":"Ein Kilo Tomaten kostet drei Euro.","pron":"ain kílo tomáten kóstet drai óiro","es":"Un kilo de jitomates cuesta 3 €."},{"en":"Auf der Flasche sind fünfundzwanzig Cent Pfand.","pron":"auf dea flashe zint fǘnf-unt-tsvántsij sent pfant","es":"La botella tiene 25 centavos de depósito."}]},{"tipo":"practica","rotulo":"¿Qué dices?","preguntas":[{"p":"Quieres pedir un café con cortesía.","ops":["Ich will Kaffee.","Ich möchte einen Kaffee, bitte.","Kaffee!"],"correcta":1},{"p":"La vendedora pregunta <i>Noch etwas?</i> Ya no quieres nada más.","ops":["Das ist alles, danke.","Noch etwas!","Ich bekomme müde."],"correcta":0},{"p":"<i>Das macht elf Euro vierzig.</i> Pagas…","ops":["40,11 €","11,40 €","14,10 €"],"correcta":1},{"p":"Er ___ ein Brot. (möchten)","ops":["möchtet","möchten","möchte"],"correcta":2,"explica":"Con er/sie/es: <b>möchte</b>, sin -t."},{"p":"Quieres saber si puedes pagar con tarjeta.","ops":["Kann ich mit Karte zahlen?","Haben Sie Karte?","Ich zahle Karte?"],"correcta":0}]},{"tipo":"completar","rotulo":"Completa la compra","voz":true,"items":[{"frase":"Ich ___ drei Brötchen, bitte.","resp":["möchte","moechte"],"es":"Quisiera tres bolillos, por favor."},{"frase":"Was ___ die Brezel?","resp":["kostet"],"es":"¿Cuánto cuesta el pretzel?"},{"frase":"Das ___ fünf Euro zehn.","resp":["macht","kostet"],"es":"Son 5,10 €."},{"frase":"Nein, danke. Das ist ___.","resp":["alles"],"es":"No, gracias. Es todo."},{"frase":"Kann ich mit ___ zahlen?","resp":["Karte"],"es":"¿Puedo pagar con tarjeta?"}]},{"tipo":"clave","items":["Pide con <b>Ich möchte…</b> o <b>Ich hätte gern…</b>; <i>er möchte</i> va sin -t.","Precios: <i>zwei Euro fünfzig</i> = 2,50 €.","<b>bekommen</b> = recibir (<i>Was bekommen Sie?</i> = ¿Qué le doy?), no «volverse».","La bolsa se paga, las botellas llevan <i>Pfand</i> y conviene traer efectivo. Pasa a la evaluación: necesitas 80%."]}],"c-aleman-a1-m5-l1":[{"tipo":"texto","texto":"En un hotel alemán todo es bastante directo y ordenado: te piden tu pasaporte, te dicen el horario del desayuno y te dan la tarjeta de la habitación. Con <b>Ich habe ein Zimmer reserviert</b> (tengo una habitación reservada) y <b>Ich möchte…</b> resuelves casi todo. Vocabulario clave: <i>das Einzelzimmer</i> (habitación sencilla), <i>das Doppelzimmer</i> (doble), <i>das Frühstück</i> (desayuno), <i>der Stock</i> (piso) y <i>das WLAN</i> (el wifi; se dice «vélan»)."},{"tipo":"tabla","titulo":"Frases para el hotel","voz":true,"colVoz":0,"encabezados":["Alemán","Español"],"filas":[["Ich habe ein Zimmer reserviert.","Tengo una habitación reservada."],["Ich möchte ein Doppelzimmer für zwei Nächte.","Quisiera una habitación doble para dos noches."],["Ist das Frühstück inklusive?","¿El desayuno está incluido?"],["Wann gibt es Frühstück?","¿A qué hora es el desayuno?"],["Wie ist das WLAN-Passwort?","¿Cuál es la contraseña del wifi?"],["Die Dusche funktioniert nicht.","La regadera no funciona."],["Das Zimmer ist zu laut.","La habitación es muy ruidosa."],["Bis wann muss ich auschecken?","¿Hasta qué hora tengo que dejar la habitación?"],["Können Sie mir ein Taxi rufen?","¿Me puede pedir un taxi?"]],"nota":"<i>Das Zimmer ist im dritten Stock</i> = la habitación está en el tercer piso. Ojo: en Alemania la planta baja es <i>das Erdgeschoss</i>, y el «primer piso» ya es el de arriba."},{"tipo":"comparar","titulo":"Calcos en la recepción","malTitulo":"Evita","mal":"<i>Ich will ein Zimmer.</i> (suena exigente)<br><i>Ich habe eine Reservation.</i> (calco de «reservación»)","bienTitulo":"Correcto","bien":"<i>Ich <b>möchte</b> ein Zimmer, bitte.</i><br><i>Ich habe eine <b>Reservierung</b>.</i> o <i>Ich habe ein Zimmer <b>reserviert</b>.</i>"},{"tipo":"dialogo","titulo":"Diálogo — Check-in en un hotel de Berlín","lineas":[{"quien":"Rezeptionistin","en":"Guten Abend! Willkommen im Hotel am Park.","es":"¡Buenas noches! Bienvenida al Hotel am Park."},{"quien":"Daniela","en":"Guten Abend! Ich habe ein Zimmer reserviert. Mein Name ist Daniela Ortiz.","es":"¡Buenas noches! Tengo una habitación reservada. Me llamo Daniela Ortiz."},{"quien":"Rezeptionistin","en":"Einen Moment, bitte. Ja, ein Einzelzimmer für drei Nächte. Ihren Pass, bitte.","es":"Un momento, por favor. Sí, una habitación sencilla para tres noches. Su pasaporte, por favor."},{"quien":"Daniela","en":"Hier, bitte. Ist das Frühstück inklusive?","es":"Aquí tiene. ¿El desayuno está incluido?"},{"quien":"Rezeptionistin","en":"Ja. Frühstück gibt es von halb sieben bis zehn Uhr.","es":"Sí. El desayuno es de seis y media a diez."},{"quien":"Daniela","en":"Und wie ist das WLAN-Passwort?","es":"¿Y cuál es la contraseña del wifi?"},{"quien":"Rezeptionistin","en":"Das steht hier auf der Karte. Ihr Zimmer ist im dritten Stock.","es":"Viene aquí en la tarjeta. Su habitación está en el tercer piso."},{"quien":"Daniela","en":"Vielen Dank!","es":"¡Muchas gracias!"}]},{"tipo":"practica","rotulo":"¿Qué dices?","preguntas":[{"p":"Llegas al hotel con reservación.","ops":["Ich habe ein Zimmer reserviert.","Ich will ein Zimmer jetzt.","Ich bin ein Zimmer."],"correcta":0},{"p":"Quieres saber si el desayuno está incluido.","ops":["Wo ist das Frühstück?","Ist das Frühstück inklusive?","Ich habe Frühstück."],"correcta":1},{"p":"No sale agua caliente de la regadera.","ops":["Die Dusche ist schön.","Ich möchte eine Dusche.","Die Dusche funktioniert nicht."],"correcta":2},{"p":"<i>Frühstück gibt es von halb sieben bis zehn.</i> El desayuno empieza a las…","ops":["7:30","6:30","7:00"],"correcta":1,"explica":"<b>halb sieben</b> = 6:30."},{"p":"Una habitación para una persona es…","ops":["ein Doppelzimmer","ein Einzelzimmer","ein Erdgeschoss"],"correcta":1}]},{"tipo":"pronunciar","rotulo":"Practica en voz alta","frases":[{"en":"Ich habe ein Zimmer reserviert.","pron":"ij hábe ain tsíma reservíat","es":"Tengo una habitación reservada."},{"en":"Ist das Frühstück inklusive?","pron":"ist das frǘshtük inklusíve","es":"¿El desayuno está incluido?"},{"en":"Wie ist das WLAN-Passwort?","pron":"vi ist das vélan-pásvort","es":"¿Cuál es la contraseña del wifi?"},{"en":"Die Heizung funktioniert nicht.","pron":"di háitsung funktsioníat nijt","es":"La calefacción no funciona."}]},{"tipo":"clave","items":["<i>Ich habe ein Zimmer reserviert</i> abre cualquier check-in.","<i>Einzelzimmer</i> = sencilla · <i>Doppelzimmer</i> = doble · <i>Frühstück</i> = desayuno.","Problemas: <i>… funktioniert nicht</i> · <i>Das Zimmer ist zu laut</i>.","Pide con <b>möchte</b>, no con <i>will</i>."]}],"c-aleman-a1-m5-l2":[{"tipo":"texto","texto":"Tres costumbres que te evitan momentos incómodos:<br><b>1)</b> El mesero no trae la cuenta hasta que la pides: <i>Zahlen, bitte!</i> o <i>Die Rechnung, bitte.</i><br><b>2)</b> Casi siempre te preguntan <b>Zusammen oder getrennt?</b> (¿juntos o por separado?). Pagar cada quien lo suyo es normalísimo, incluso en pareja.<br><b>3)</b> La propina (<i>das Trinkgeld</i>), de más o menos 5 a 10%, <b>no se deja en la mesa</b>: se dice al pagar. Si la cuenta es 27,40 €, dices <i>Dreißig, bitte</i> o <i>Machen Sie dreißig</i>. Si pagas en efectivo y no quieres cambio: <i>Stimmt so.</i><br>Y el agua: si pides <i>Wasser</i>, muchas veces llega mineral con gas. Si la quieres natural, di <i>stilles Wasser</i> o <i>ohne Kohlensäure</i>."},{"tipo":"tabla","titulo":"Frases para el restaurante","voz":true,"colVoz":0,"encabezados":["Alemán","Español"],"filas":[["Einen Tisch für zwei, bitte.","Una mesa para dos, por favor."],["Die Speisekarte, bitte.","La carta, por favor."],["Was empfehlen Sie?","¿Qué me recomienda?"],["Ich nehme das Schnitzel.","Voy a querer el schnitzel."],["Für mich einen Salat, bitte.","Para mí una ensalada, por favor."],["Ein Wasser ohne Kohlensäure, bitte.","Un agua sin gas, por favor."],["Hat es geschmeckt?","¿Le gustó la comida?"],["Zahlen, bitte!","¡La cuenta, por favor!"],["Zusammen oder getrennt?","¿Juntos o por separado?"],["Machen Sie dreißig, bitte.","Cóbrese treinta, por favor. (con propina)"],["Stimmt so.","Quédese con el cambio."]]},{"tipo":"comparar","titulo":"La propina a la alemana","malTitulo":"Evita","mal":"Pagar la cuenta exacta y dejar monedas en la mesa al irte.<br>Esperar a que te traigan la cuenta sin pedirla.","bienTitulo":"Correcto","bien":"Al pagar, di el total <b>con</b> propina: cuenta de 18,60 € → <i>Zwanzig, bitte.</i><br>Cuando quieras irte: <i>Zahlen, bitte!</i>"},{"tipo":"dialogo","titulo":"Diálogo — Cena en un restaurante de Berlín","lineas":[{"quien":"Kellner","en":"Guten Abend! Haben Sie reserviert?","es":"¡Buenas noches! ¿Tienen reservación?"},{"quien":"Marco","en":"Nein. Haben Sie einen Tisch für zwei?","es":"No. ¿Tiene una mesa para dos?"},{"quien":"Kellner","en":"Ja, bitte hier. Was möchten Sie trinken?","es":"Sí, por aquí. ¿Qué desean tomar?"},{"quien":"Marco","en":"Ein stilles Wasser, bitte.","es":"Un agua natural, por favor."},{"quien":"Lucía","en":"Für mich eine Apfelschorle. Und ich nehme die Currywurst mit Pommes.","es":"Para mí un agua mineral con jugo de manzana. Y voy a querer la currywurst con papas."},{"quien":"Lucía","en":"Zahlen, bitte!","es":"¡La cuenta, por favor!"},{"quien":"Kellner","en":"Zusammen oder getrennt?","es":"¿Juntos o por separado?"},{"quien":"Lucía","en":"Getrennt, bitte.","es":"Por separado, por favor."},{"quien":"Kellner","en":"Die Currywurst und die Apfelschorle: Das macht elf Euro achtzig.","es":"La currywurst y el agua con jugo: son once euros con ochenta."},{"quien":"Lucía","en":"Machen Sie dreizehn, bitte.","es":"Cóbrese trece, por favor."},{"quien":"Kellner","en":"Vielen Dank! Schönen Abend noch!","es":"¡Muchas gracias! ¡Que pasen buena noche!"}]},{"tipo":"practica","rotulo":"¿Qué haces o qué dices?","preguntas":[{"p":"Terminaste de comer y quieres pagar.","ops":["Zahlen, bitte!","Stimmt so!","Guten Appetit!"],"correcta":0},{"p":"El mesero pregunta <i>Zusammen oder getrennt?</i> Cada quien paga lo suyo. Dices…","ops":["Zusammen, bitte.","Getrennt, bitte.","Ohne Kohlensäure."],"correcta":1},{"p":"Tu cuenta es 23,50 € y quieres dejar algo más de 2 € de propina.","ops":["Ich lasse das Geld auf dem Tisch.","Dreiundzwanzig, bitte.","Machen Sie sechsundzwanzig, bitte."],"correcta":2},{"p":"Quieres agua natural.","ops":["Ein Wasser mit Kohlensäure.","Ein stilles Wasser, bitte.","Ein Wasser getrennt."],"correcta":1},{"p":"El mesero pregunta <i>Hat es geschmeckt?</i> Contestas…","ops":["Ja, sehr gut, danke!","Ja, getrennt.","Nein, zahlen."],"correcta":0}]},{"tipo":"completar","rotulo":"Completa","voz":true,"items":[{"frase":"Einen ___ für zwei, bitte.","resp":["Tisch"],"es":"Una mesa para dos, por favor."},{"frase":"Ich ___ das Schnitzel.","resp":["nehme"],"es":"Voy a querer el schnitzel."},{"frase":"Ein Wasser ohne ___, bitte.","resp":["Kohlensäure","Kohlensaeure"],"es":"Un agua sin gas, por favor."},{"frase":"___, bitte!","resp":["Zahlen"],"es":"¡La cuenta, por favor!"},{"frase":"Zusammen oder ___?","resp":["getrennt"],"es":"¿Juntos o por separado?"}]},{"tipo":"clave","items":["Pide la cuenta tú: <i>Zahlen, bitte!</i>","<i>Zusammen oder getrennt?</i> = ¿juntos o por separado?","Propina de 5 a 10%, dicha al pagar: <i>Machen Sie dreißig</i> · <i>Stimmt so</i>.","Agua natural = <i>stilles Wasser</i> u <i>ohne Kohlensäure</i>."]}],"c-aleman-a1-m5-l3":[{"tipo":"texto","texto":"Para hablar del pasado en la conversación, los alemanes usan casi siempre el <b>Perfekt</b>: <b>haben</b> conjugado en segundo lugar + <b>participio al final</b>. Es la misma «cajita» de los verbos separables:<br><i>Ich <b>habe</b> gestern Tacos <b>gegessen</b>.</i> (Ayer comí tacos.)<br>Los participios regulares se forman con <b>ge- + raíz + -t</b>: <i>machen → gemacht</i>. Algunos muy comunes son irregulares y terminan en <b>-en</b>: <i>essen → gegessen</i>. Un aviso para más adelante: los verbos de movimiento como <i>fahren, gehen</i> y <i>fliegen</i> usan <b>sein</b>: <i>Ich <b>bin</b> nach Berlin gefahren.</i> Por ahora apréndelo como frase hecha; lo verás a fondo en A2."},{"tipo":"tabla","titulo":"Participios que usarás mucho","voz":true,"colVoz":2,"encabezados":["Verbo","Participio","Ejemplo"],"filas":[["machen (hacer)","gemacht","Was hast du gemacht?"],["kaufen (comprar)","gekauft","Ich habe ein Geschenk gekauft."],["arbeiten (trabajar)","gearbeitet","Er hat viel gearbeitet."],["spielen (jugar)","gespielt","Wir haben Fußball gespielt."],["essen (comer)","gegessen","Ich habe Tacos gegessen."],["trinken (tomar)","getrunken","Wir haben Bier getrunken."],["sehen (ver)","gesehen","Hast du den Film gesehen?"],["einkaufen (hacer compras)","eingekauft","Ich habe am Samstag eingekauft."],["besuchen (visitar)","besucht","Wir haben das Museum besucht."],["fotografieren (fotografiar)","fotografiert","Ich habe viel fotografiert."]],"nota":"Sin <b>ge-</b>: los verbos que terminan en <b>-ieren</b> (<i>fotografiert, telefoniert, reserviert</i>) y los que empiezan con <b>be-</b> o <b>ver-</b> (<i>besucht, verkauft</i>). En los separables, el <i>ge-</i> va en medio: <i>ein<b>ge</b>kauft</i>."},{"tipo":"comparar","titulo":"El participio va al final","malTitulo":"Evita","mal":"<i>Ich habe gegessen Tacos.</i><br><i>Gestern ich habe gearbeitet.</i><br><i>Ich habe gekauft ein Geschenk.</i>","bienTitulo":"Correcto","bien":"<i>Ich habe Tacos <b>gegessen</b>.</i><br><i>Gestern <b>habe</b> ich gearbeitet.</i> (verbo en segundo lugar)<br><i>Ich habe ein Geschenk <b>gekauft</b>.</i>"},{"tipo":"escuchar","rotulo":"El fin de semana de Diego","frases":[{"en":"Am Samstag habe ich lange geschlafen.","pron":"am zámstaak hábe ij lángue gueshláfen","es":"El sábado dormí mucho."},{"en":"Dann habe ich mit meinem Sohn Fußball gespielt.","pron":"dan hábe ij mit máinem zon fúsbal gueshpílt","es":"Luego jugué futbol con mi hijo."},{"en":"Am Abend haben wir Pizza gegessen.","pron":"am ábent háben via pítsa guegésen","es":"En la noche comimos pizza."},{"en":"Am Sonntag habe ich meine Eltern besucht.","pron":"am zóntaak hábe ij máine éltern bezújt","es":"El domingo visité a mis papás."},{"en":"Und was hast du gemacht?","pron":"unt vas hast du guemájt","es":"¿Y tú qué hiciste?"}]},{"tipo":"ordenar","rotulo":"Arma la frase en pasado","voz":true,"items":[{"frase":"Ich habe gestern Tacos gegessen.","es":"Ayer comí tacos.","otras":["Gestern habe ich Tacos gegessen."]},{"frase":"Hast du am Wochenende gearbeitet?","es":"¿Trabajaste el fin de semana?"},{"frase":"Wir haben das Museum besucht.","es":"Visitamos el museo.","otras":["Das Museum haben wir besucht."]},{"frase":"Am Samstag habe ich eingekauft.","es":"El sábado hice las compras.","otras":["Ich habe am Samstag eingekauft."]}]},{"tipo":"practica","rotulo":"Elige la forma correcta","preguntas":[{"p":"Participio de <i>kaufen</i>:","ops":["gekauft","gekaufen","kaufte"],"correcta":0},{"p":"Participio de <i>trinken</i>:","ops":["getrinkt","getrunken","trinkt"],"correcta":1},{"p":"«Ayer trabajé mucho»","ops":["Gestern ich habe viel gearbeitet.","Gestern habe ich viel gearbeitet.","Gestern habe ich gearbeitet viel."],"correcta":1},{"p":"Participio de <i>fotografieren</i>:","ops":["gefotografiert","fotografiert","fotografieren"],"correcta":1,"explica":"Los verbos en <b>-ieren</b> no llevan <i>ge-</i>."},{"p":"«¿Qué hiciste?»","ops":["Was hast du gemacht?","Was bist du gemacht?","Was hast du machen?"],"correcta":0}]},{"tipo":"completar","rotulo":"Completa con haben o con el participio","voz":true,"items":[{"frase":"Ich ___ gestern Pizza gegessen.","resp":["habe"],"es":"Ayer comí pizza."},{"frase":"Wir haben Fußball ___.","resp":["gespielt"],"es":"Jugamos futbol. (spielen)"},{"frase":"Was ___ du am Wochenende gemacht?","resp":["hast"],"es":"¿Qué hiciste el fin de semana?"},{"frase":"Sie hat einen Film ___.","resp":["gesehen"],"es":"Ella vio una película. (sehen)"},{"frase":"Ich habe ein Geschenk ___.","resp":["gekauft"],"es":"Compré un regalo. (kaufen)"}]},{"tipo":"clave","items":["Perfekt = <b>haben</b> en segundo lugar + <b>participio al final</b>.","Regulares: <i>ge-…-t</i> (<i>gemacht, gekauft</i>); irregulares en <i>-en</i> (<i>gegessen, getrunken, gesehen</i>).","Sin <i>ge-</i>: <i>-ieren</i>, <i>be-</i>, <i>ver-</i>. Separables: <i>eingekauft</i>.","Movimiento con <b>sein</b>: <i>Ich bin nach Berlin gefahren</i>."]}],"c-aleman-a1-m5-l4":[{"tipo":"texto","texto":"Los posesivos funcionan como <i>ein</i>: <b>sin -e</b> con palabras <i>der</i> y <i>das</i>, <b>con -e</b> con <i>die</i> y en plural: <i>mein Vater, mein Kind, <b>meine</b> Mutter, <b>meine</b> Eltern</i>. Son: <b>mein</b> (mi), <b>dein</b> (tu), <b>sein</b> (su, de él), <b>ihr</b> (su, de ella), <b>unser</b> (nuestro) e <b>Ihr</b> (su, de usted, con mayúscula).<br>Para invitar: <i>Hast du am Samstag Zeit?</i> (¿Tienes tiempo el sábado?) y <i>Möchtest du zum Essen kommen?</i> Si te invitan a una casa, llega <b>puntual</b> (la puntualidad cuenta mucho) y lleva un detalle: flores, un vino o algo típico de México."},{"tipo":"tabla","titulo":"La familia","voz":true,"colVoz":0,"encabezados":["Alemán","Español"],"filas":[["die Mutter · der Vater","la mamá · el papá"],["die Eltern","los papás (padre y madre)"],["der Bruder · die Schwester","el hermano · la hermana"],["die Geschwister","los hermanos (en general)"],["der Sohn · die Tochter","el hijo · la hija"],["das Kind · die Kinder","el niño, el hijo · los niños, los hijos"],["mein Mann · meine Frau","mi esposo · mi esposa"],["die Großeltern","los abuelos"],["die Oma · der Opa","la abuela · el abuelo (cariñoso)"]],"nota":"Para aceptar: <i>Gern! / Sehr gern! / Super, danke!</i> Para decir que no: <i>Leider kann ich nicht.</i> (Desafortunadamente no puedo) · <i>Vielleicht ein anderes Mal.</i> (Tal vez otro día)."},{"tipo":"comparar","titulo":"Falsos amigos en la fiesta","malTitulo":"Evita pensar que…","mal":"<i>Gift</i> es un regalo, como en inglés.<br><i>Kind</i> significa «amable», como en inglés.","bienTitulo":"En realidad…","bien":"<i>das <b>Gift</b></i> = el <b>veneno</b>. El regalo es <i>das <b>Geschenk</b></i>: <i>Ich bringe ein Geschenk mit.</i><br><i>das <b>Kind</b></i> = el niño, el hijo. «Amable» es <i><b>nett</b></i> o <i><b>freundlich</b></i>."},{"tipo":"dialogo","titulo":"Diálogo — Una invitación en la oficina","lineas":[{"quien":"Jonas","en":"Diego, hast du am Samstag Zeit?","es":"Diego, ¿tienes tiempo el sábado?"},{"quien":"Diego","en":"Ja, warum?","es":"Sí, ¿por qué?"},{"quien":"Jonas","en":"Wir grillen im Garten. Möchtest du kommen? Deine Frau und deine Kinder sind auch eingeladen.","es":"Vamos a hacer carne asada en el jardín. ¿Quieres venir? Tu esposa y tus hijos también están invitados."},{"quien":"Diego","en":"Sehr gern! Danke für die Einladung. Soll ich etwas mitbringen?","es":"¡Con mucho gusto! Gracias por la invitación. ¿Llevo algo?"},{"quien":"Jonas","en":"Vielleicht einen Salat?","es":"¿Tal vez una ensalada?"},{"quien":"Diego","en":"Klar! Um wie viel Uhr?","es":"¡Claro! ¿A qué hora?"},{"quien":"Jonas","en":"Um drei Uhr. Meine Eltern kommen auch.","es":"A las tres. Mis papás también vienen."},{"quien":"Diego","en":"Super, bis Samstag!","es":"¡Perfecto, hasta el sábado!"}]},{"tipo":"practica","rotulo":"Elige la opción correcta","preguntas":[{"p":"«Mi hermana»","ops":["mein Schwester","meine Schwester","meinen Schwester"],"correcta":1},{"p":"«Su papá» (de ella)","ops":["ihr Vater","sein Vater","ihre Vater"],"correcta":0,"explica":"De ella = <b>ihr</b>; <i>Vater</i> es <i>der</i>, así que sin -e."},{"p":"Te invitan, pero ese día trabajas. Dices…","ops":["Gern!","Leider kann ich nicht. Vielleicht ein anderes Mal?","Gleichfalls!"],"correcta":1},{"p":"Quieres llevar un regalo. Dices…","ops":["Ich bringe ein Gift mit.","Ich bringe ein Geschenk mit.","Ich bringe ein Kind mit."],"correcta":1},{"p":"<i>Meine Geschwister</i> son…","ops":["mis abuelos","mis hermanos","mis hijos"],"correcta":1}]},{"tipo":"completar","rotulo":"¿mein o meine?","voz":true,"items":[{"frase":"Das ist ___ Mutter.","resp":["meine"],"es":"Ella es mi mamá. (die Mutter)"},{"frase":"Das ist ___ Bruder.","resp":["mein"],"es":"Él es mi hermano. (der Bruder)"},{"frase":"Das sind ___ Eltern.","resp":["meine"],"es":"Ellos son mis papás. (plural)"},{"frase":"Hast du am Samstag ___?","resp":["Zeit"],"es":"¿Tienes tiempo el sábado?"},{"frase":"Danke für die ___!","resp":["Einladung"],"es":"¡Gracias por la invitación!"}]},{"tipo":"tarjetas","rotulo":"La familia","voz":true,"vozEn":"reverso","instruccion":"Di la palabra en alemán, con su artículo, antes de voltear.","tarjetas":[{"frente":"la mamá","reverso":"die Mutter","ej":"Meine Mutter wohnt in Puebla."},{"frente":"el papá","reverso":"der Vater","ej":"Mein Vater ist Rentner."},{"frente":"la hija","reverso":"die Tochter","ej":"Meine Tochter ist zehn Jahre alt."},{"frente":"el hijo","reverso":"der Sohn","ej":"Mein Sohn spielt gern Fußball."},{"frente":"los hermanos","reverso":"die Geschwister","ej":"Ich habe drei Geschwister."},{"frente":"el regalo","reverso":"das Geschenk","ej":"Das Geschenk ist für dich."}]},{"tipo":"clave","items":["<b>mein</b> con der/das · <b>meine</b> con die y plural.","<b>sein</b> = de él · <b>ihr</b> = de ella · <b>Ihr</b> = de usted.","Invitar: <i>Hast du Zeit? Möchtest du kommen?</i> · Aceptar: <i>Sehr gern!</i> · Rechazar: <i>Leider kann ich nicht.</i>","<b>Gift</b> = veneno · <b>Geschenk</b> = regalo · <b>Kind</b> = niño."]}],"c-aleman-a1-m5-l5":[{"tipo":"texto","texto":"Mariana es de Guadalajara y viaja sola a Berlín. Vas a acompañarla y a usar todo lo que aprendiste: saludos, <i>Sie</i>, números y precios, <i>es gibt</i>, direcciones, transporte, <i>ich möchte</i>, el acusativo, el <i>Perfekt</i> y, sobre todo, el verbo en segunda posición. Si algo se te olvidó, no pasa nada: regresa a la lección y vuelve. Así se aprende un idioma."},{"tipo":"dialogo","titulo":"Diálogo — En el aeropuerto de Berlín","lineas":[{"quien":"Mariana","en":"Guten Tag! Wie komme ich zum Alexanderplatz?","es":"¡Buenas tardes! ¿Cómo llego a Alexanderplatz?"},{"quien":"Info","en":"Nehmen Sie die S-Bahn. Sie fährt alle zwanzig Minuten.","es":"Tome el tren urbano. Pasa cada veinte minutos."},{"quien":"Mariana","en":"Muss ich umsteigen?","es":"¿Tengo que transbordar?"},{"quien":"Info","en":"Nein, die S-Bahn fährt direkt.","es":"No, el tren urbano va directo."},{"quien":"Mariana","en":"Und wo kann ich eine Fahrkarte kaufen?","es":"¿Y dónde puedo comprar un boleto?"},{"quien":"Info","en":"Am Automaten, dort drüben.","es":"En la máquina, allá."},{"quien":"Mariana","en":"Vielen Dank! Schönen Tag noch!","es":"¡Muchas gracias! ¡Que tenga buen día!"},{"quien":"Info","en":"Danke, gleichfalls! Willkommen in Berlin!","es":"¡Gracias, igualmente! ¡Bienvenida a Berlín!"}]},{"tipo":"escuchar","rotulo":"La postal de Mariana","frases":[{"en":"Liebe Sofía, ich bin seit drei Tagen in Berlin.","pron":"líbe sofía, ij bin zait drai táguen in berlín","es":"Querida Sofía: estoy en Berlín desde hace tres días."},{"en":"Gestern habe ich das Brandenburger Tor gesehen und viele Fotos gemacht.","es":"Ayer vi la Puerta de Brandeburgo y tomé muchas fotos."},{"en":"Am Abend habe ich mit Lukas eine Currywurst gegessen.","pron":"am ábent hábe ij mit lúkas áine kárivurst guegésen","es":"En la noche comí una currywurst con Lukas."},{"en":"Heute kaufe ich Geschenke für meine Familie.","pron":"hóite káufe ij gueshénke füa máine famílie","es":"Hoy compro regalos para mi familia."},{"en":"Morgen fahre ich mit dem Zug nach München. Liebe Grüße!","pron":"mórguen fáre ij mit dem tsuk naj mǘnjen. líbe grǘse","es":"Mañana me voy en tren a Múnich. ¡Saludos con cariño!"}]},{"tipo":"practica","rotulo":"Repaso: ¿qué dice Mariana?","preguntas":[{"p":"Llega al hotel a las 9 de la noche. Saluda con…","ops":["Gute Nacht!","Guten Abend!","Guten Morgen!"],"correcta":1},{"p":"Quiere saber si hay un cajero cerca.","ops":["Gibt es hier in der Nähe einen Geldautomaten?","Hat hier Geldautomat?","Wo gibt Geldautomat?"],"correcta":0},{"p":"En la panadería pide dos pretzels con cortesía.","ops":["Ich will zwei Brezeln.","Zwei Brezeln!","Ich möchte zwei Brezeln, bitte."],"correcta":2},{"p":"Le cuenta a su amiga que ayer vio un museo.","ops":["Gestern ich habe ein Museum gesehen.","Gestern habe ich ein Museum gesehen.","Gestern habe ich gesehen ein Museum."],"correcta":1},{"p":"La cuenta es 14,30 € y quiere dejar propina.","ops":["Machen Sie sechzehn, bitte.","Getrennt, bitte.","Das Geld ist auf dem Tisch."],"correcta":0}]},{"tipo":"completar","rotulo":"Completa el viaje de Mariana","voz":true,"items":[{"frase":"Ich ___ Mexikanerin, aus Guadalajara.","resp":["bin"],"es":"Soy mexicana, de Guadalajara."},{"frase":"Ich bin dreißig Jahre ___.","resp":["alt"],"es":"Tengo treinta años."},{"frase":"Ich fahre mit ___ S-Bahn zum Alexanderplatz.","resp":["der"],"es":"Voy en el tren urbano a Alexanderplatz."},{"frase":"Ich möchte ___ Kaffee, bitte.","resp":["einen"],"es":"Quisiera un café, por favor."},{"frase":"Gestern habe ich viele Fotos ___.","resp":["gemacht"],"es":"Ayer tomé muchas fotos."},{"frase":"Zahlen, bitte! — Zusammen oder ___?","resp":["getrennt"],"es":"¡La cuenta, por favor! — ¿Juntos o por separado?"}]},{"tipo":"ordenar","rotulo":"Arma las frases del viaje","voz":true,"items":[{"frase":"Ich komme aus Mexiko, aus Guadalajara.","es":"Soy de México, de Guadalajara."},{"frase":"Morgen fahre ich mit dem Zug nach München.","es":"Mañana me voy en tren a Múnich.","otras":["Ich fahre morgen mit dem Zug nach München."]},{"frase":"Gestern habe ich eine Currywurst gegessen.","es":"Ayer comí una currywurst.","otras":["Ich habe gestern eine Currywurst gegessen."]},{"frase":"Gibt es hier in der Nähe eine Apotheke?","es":"¿Hay una farmacia por aquí cerca?"}]},{"tipo":"relacionar","rotulo":"Repaso de falsos amigos: ¿qué significan de verdad?","voz":true,"pares":[["das Gift","el veneno"],["der Rat","el consejo"],["das Kind","el niño"],["also","entonces, bueno"],["die Rente","la pensión de jubilación"],["bekommen","recibir"],["der Chef","el jefe"]]},{"tipo":"reflexion","rotulo":"Tu postal","pregunta":"Imagina que estás de viaje en Berlín o en Múnich. Escribe una postal de 5 frases a un amigo: dónde estás, qué hiciste ayer (dos cosas), qué comiste y adónde vas mañana. Cuida el verbo en segundo lugar. Después léela en voz alta.","ayuda":"Lieber… / Liebe…, ich bin in… Gestern habe ich… gesehen und… gekauft. Am Abend habe ich… gegessen. Morgen fahre ich nach… Liebe Grüße!"},{"tipo":"clave","items":["Saludar, usar <i>Sie</i> y pedir con <i>ich möchte</i> te abre todas las puertas.","El verbo en <b>segundo lugar</b>, siempre: <i>Morgen <b>fahre</b> ich nach München.</i>","Presente para hoy y mañana; <i>haben</i> + participio para ayer.","Pasa a la evaluación final del módulo: necesitas 80%. Herzlichen Glückwunsch! (¡Muchas felicidades!)"]}]},"q":{"c-aleman-a1-m1":[{"p":"Llegas a un restaurante a las 8 de la noche. Saludas con…","ops":["Gute Nacht!","Guten Abend!","Guten Morgen!","Tschüss!"],"correcta":1},{"p":"Hablas con una clienta en tu hotel. ¿Qué pregunta es la adecuada?","ops":["Wie geht's, du?","Wie bist du?","Wie geht es Ihnen?","Wie geht es dir?"],"correcta":2},{"p":"«Estoy bien, gracias» se dice…","ops":["Ich bin gut, danke.","Mir geht es gut, danke.","Mich geht es gut, danke.","Ich geht gut, danke."],"correcta":1},{"p":"Una mujer dice «Soy mexicana»:","ops":["Ich bin Mexikanerin.","Ich bin Mexikaner.","Ich bin Mexiko.","Ich habe Mexikanerin."],"correcta":0},{"p":"Completa: <i>Wir ___ aus Puebla.</i>","ops":["bist","ist","seid","sind"],"correcta":3},{"p":"Les preguntas a dos amigos «¿Ustedes vienen?». ¿Qué pronombre usas?","ops":["du","ihr","er"],"correcta":1},{"p":"¿Cómo suena la <b>w</b> de <i>Wasser</i>?","ops":["Como la «gu» de «guante»","Como una «u»","Como una «v»"],"correcta":2},{"p":"¿Por qué en alemán se escribe <i>Ich trinke Kaffee</i> con K mayúscula?","ops":["Porque es una marca","Porque todos los sustantivos van con mayúscula","Porque es la primera palabra","Porque es un error común"],"correcta":1}],"c-aleman-a1-m2":[{"p":"¿Cómo se dice 45?","ops":["vierzigfünf","fünfundvierzig","vierundfünfzig","fünfvierzig"],"correcta":1},{"p":"«Tengo 28 años» se dice…","ops":["Ich habe achtundzwanzig Jahre.","Ich habe achtundzwanzig Jahre alt.","Ich bin achtundzwanzig Jahre alt.","Mir ist achtundzwanzig."],"correcta":2},{"p":"Completa: <i>Er ___ zwei Kinder.</i>","ops":["hat","habt","hast","haben"],"correcta":0},{"p":"«Ella es médica»","ops":["Sie hat Ärztin.","Sie ist Arzt.","Sie ist Ärztin."],"correcta":2},{"p":"Un amigo alemán te cuenta que su papá ya es <i>Rentner</i>. Significa que…","ops":["renta un departamento","es dueño de casas en renta","trabaja en un banco","está jubilado"],"correcta":3},{"p":"¿Qué artículo lleva <i>Zeitung</i>?","ops":["der","die","das"],"correcta":1},{"p":"«¿Dónde vives?»","ops":["Wer wohnst du?","Wo du wohnst?","Wo wohnst du?","Wohin wohnst du?"],"correcta":2},{"p":"¿Cuál frase respeta el verbo en segunda posición?","ops":["Morgen arbeite ich.","Morgen ich arbeite.","Ich morgen arbeite.","Arbeite morgen ich."],"correcta":0}],"c-aleman-a1-m3":[{"p":"«Él trabaja mucho»","ops":["Er arbeit viel.","Er arbeitet viel.","Er arbeiten viel.","Er ist arbeiten viel."],"correcta":1},{"p":"«Me levanto a las seis»","ops":["Ich aufstehe um sechs Uhr.","Um sechs Uhr ich stehe auf.","Ich stehe um sechs Uhr auf.","Ich stehe um sechs Uhr aufstehen."],"correcta":2},{"p":"<i>Es ist halb acht</i> significa…","ops":["8:30","7:30","8:15","7:15"],"correcta":1},{"p":"<i>Viertel vor zehn</i> es…","ops":["9:45","10:15","10:45","9:15"],"correcta":0},{"p":"Completa: <i>Ich arbeite ___ Montag.</i>","ops":["im","um","am","in"],"correcta":2},{"p":"«Me gusta cocinar»","ops":["Ich gern koche.","Ich koche gern.","Ich mag gern kochen."],"correcta":1},{"p":"«No tengo coche»","ops":["Ich habe nicht Auto.","Ich habe keine Auto.","Ich habe kein Auto.","Ich nicht habe Auto."],"correcta":2},{"p":"Tu colega alemán dice <i>Also, wir fangen an.</i> ¿Qué significa <i>also</i> aquí?","ops":["También","Además","Tampoco","Bueno, entonces"],"correcta":3}],"c-aleman-a1-m4":[{"p":"«¿Hay una farmacia por aquí?»","ops":["Hat es hier eine Apotheke?","Gibt es hier eine Apotheke?","Es gibt hier Apotheke?","Ist hier Apotheke gibt?"],"correcta":1},{"p":"Completa: <i>Wie komme ich ___ Bahnhof?</i> (der Bahnhof)","ops":["zur","zum","zu die"],"correcta":1},{"p":"«Voy en metro al trabajo»","ops":["Ich gehe mit der U-Bahn zur Arbeit.","Ich fahre in U-Bahn zur Arbeit.","Ich fahre mit der U-Bahn zur Arbeit."],"correcta":2},{"p":"Completa: <i>Ich brauche ___ Stift.</i> (der Stift)","ops":["einen","ein","eine","einer"],"correcta":0},{"p":"En el acusativo, ¿qué artículo cambia?","ops":["die → den","das → den","der → den","Todos cambian"],"correcta":2},{"p":"¿Cómo se dice 7,80 €?","ops":["achtzig Euro sieben","sieben Euro achtzehn","siebzig Euro acht","sieben Euro achtzig"],"correcta":3},{"p":"En la panadería te preguntan <i>Was bekommen Sie?</i> Significa…","ops":["¿En qué se convierte?","¿Qué le doy?","¿Qué recibió ayer?"],"correcta":1},{"p":"«Quisiera un café, por favor» (der Kaffee)","ops":["Ich möchte einen Kaffee, bitte.","Ich will ein Kaffee.","Ich möchte ein Kaffee, bitte.","Gib mir Kaffee."],"correcta":0}],"c-aleman-a1-m5":[{"p":"En la recepción del hotel, ¿cuál es la forma más amable?","ops":["Ich will ein Zimmer.","Ich möchte ein Zimmer für zwei Nächte, bitte.","Zimmer, zwei Nächte!","Ich habe Zimmer."],"correcta":1},{"p":"El mesero pregunta <i>Zusammen oder getrennt?</i> Quiere saber si…","ops":["van a pagar juntos o por separado","quieren mesa adentro o afuera","quieren agua con gas o sin gas"],"correcta":0},{"p":"Tu cuenta es 27,40 € y quieres dejar propina. Dices…","ops":["Das Trinkgeld ist auf dem Tisch.","Zusammen, bitte.","Ich bekomme dreißig.","Machen Sie dreißig, bitte."],"correcta":3},{"p":"«Ayer comí tacos»","ops":["Gestern ich habe Tacos gegessen.","Gestern habe ich gegessen Tacos.","Gestern habe ich Tacos gegessen.","Gestern habe ich Tacos geesst."],"correcta":2},{"p":"Participio de <i>kaufen</i>:","ops":["gekauft","gekaufen","kaufte","gekauf"],"correcta":0},{"p":"«Mi mamá y mi papá»","ops":["mein Mutter und mein Vater","meine Mutter und meine Vater","meine Mutter und mein Vater"],"correcta":2},{"p":"Dices que vas a llevar un <i>Gift</i> a la fiesta y tu amigo alemán se asusta. ¿Por qué?","ops":["Gift es una grosería","Gift significa veneno","Gift significa deuda"],"correcta":1},{"p":"Te invitan: <i>Möchtest du am Samstag zum Essen kommen?</i> Aceptas con…","ops":["Leider kann ich nicht.","Gleichfalls!","Sehr gern! Danke für die Einladung.","Freut mich auch!"],"correcta":2}]}});
